// questions-alert-investigation.js
// Cyber Defense Runner - Alert Investigation question bank (100 questions).
// Standalone data file. NOT yet merged into questions.js.
// Distribution: tiers 50 Beginner / 35 Intermediate / 15 Advanced.
//               correct index balanced 25 / 25 / 25 / 25 across A/B/C/D.

const ALERT_INVESTIGATION_QUESTIONS = [
  { id:"alert-investigation-001", tier:"Beginner", topic:"Alert Investigation", prompt:"What is 'triage' in handling security alerts?", options:["Quickly assessing and prioritizing alerts to decide what to handle first","Automatically deleting every alert that arrives","Encrypting all of the SOC's stored data","Backing up the alert logs to cold storage"], correct:0, explain:"Triage is the first review that sorts and prioritizes alerts so the most important get attention first.", reward:"Triage Focus" },
  { id:"alert-investigation-002", tier:"Beginner", topic:"Alert Investigation", prompt:"What does the 'severity' of an alert describe?", options:["The name of the detection rule","How serious the potential impact is","Which sensor produced the alert","How long the alert has been open"], correct:1, explain:"Severity reflects how damaging the issue could be, helping prioritize response.", reward:"Severity Sense" },
  { id:"alert-investigation-003", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a 'false positive' alert?", options:["A real attack that was completely missed","Routine backup of the alert data","Patching applied to a detection sensor","An alert that flags benign activity as malicious"], correct:3, explain:"A false positive is harmless activity wrongly flagged as a threat.", reward:"Signal Clarity" },
  { id:"alert-investigation-004", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is gathering evidence important during an investigation?", options:["To make the final report look nicer","To slow the investigation down on purpose","To support conclusions and any later response or reporting","To delete data that is no longer needed"], correct:2, explain:"Evidence backs up the analyst's conclusions and supports response, reporting, or legal needs.", reward:"Evidence Care" },
  { id:"alert-investigation-005", tier:"Beginner", topic:"Alert Investigation", prompt:"Why build a timeline during an investigation?", options:["To make the case file look nicer","To understand the order of events and what happened when","To slow the investigation down","To delete data that is not needed"], correct:1, explain:"A timeline orders events so you can see how an incident unfolded.", reward:"Timeline Sense" },
  { id:"alert-investigation-006", tier:"Beginner", topic:"Alert Investigation", prompt:"Why identify the affected user account in an alert?", options:["To know whose access may be misused and what they can reach","To choose a color theme for the report","To slow the investigation down","To delete the related log entries"], correct:0, explain:"Knowing the user shows what access is at risk and helps scope the incident.", reward:"Scope Focus" },
  { id:"alert-investigation-007", tier:"Beginner", topic:"Alert Investigation", prompt:"Why identify the affected host (computer) in an alert?", options:["To choose a theme for the dashboard","To slow the response down on purpose","To know which system is involved and what it does","To delete the host's log entries"], correct:2, explain:"Identifying the host shows what system is at risk and its role, guiding response.", reward:"Host Focus" },
  { id:"alert-investigation-008", tier:"Beginner", topic:"Alert Investigation", prompt:"What does a 'process tree' show an analyst?", options:["The team's current data backup plan","A map of the entire office network","The firewall's current rule list","Which process started which, in a parent-child relationship"], correct:3, explain:"A process tree shows parent-child relationships, revealing what launched what.", reward:"Process Insight" },
  { id:"alert-investigation-009", tier:"Beginner", topic:"Alert Investigation", prompt:"Why are recorded command lines useful in an investigation?", options:["They can reveal exactly what a program was told to do","They quietly set the dashboard theme","They help charge the device battery","They print the desktop wallpaper image"], correct:0, explain:"Captured command-line arguments often show the attacker's exact intent and actions.", reward:"Command Insight" },
  { id:"alert-investigation-010", tier:"Beginner", topic:"Alert Investigation", prompt:"Why review a host's network connections during an alert?", options:["To choose nicer colors for the report","To see what it is communicating with, which may reveal a threat","To slow the whole investigation down","To delete the host's old log files"], correct:1, explain:"Connections can reveal contact with malicious servers or internal spread.", reward:"Connection Insight" },
  { id:"alert-investigation-011", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a file 'hash' used for in investigations?", options:["Creating a backup copy of the file","Encrypting the entire disk while at rest","Speeding up how fast the file opens","Uniquely identifying a file so it can be looked up or compared"], correct:3, explain:"A hash is a fingerprint of a file's contents, used to identify or check it against known samples.", reward:"Hash Insight" },
  { id:"alert-investigation-012", tier:"Beginner", topic:"Alert Investigation", prompt:"Why do analysts pull from multiple log sources during an investigation?", options:["Adding a few more colors to the report","To slow the whole investigation down","Different sources give different pieces of the full picture","Deleting data that is no longer needed"], correct:2, explain:"Combining logs from endpoint, network, and identity builds a more complete view of an incident.", reward:"Log Source Sense" },
  { id:"alert-investigation-013", tier:"Beginner", topic:"Alert Investigation", prompt:"What does it mean to 'escalate' an alert?", options:["Quietly delete it from the queue","Raise it to a higher tier or team for deeper handling","Ignore it and move to the next one","Encrypt it before storing the record"], correct:1, explain:"Escalation passes an alert to more senior responders when it exceeds the current handler's scope.", reward:"Escalation Sense" },
  { id:"alert-investigation-014", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the goal of 'containment' during an incident?", options:["Stop the threat from spreading or causing more damage","Speed up the affected computer","Delete all of the system logs","Order brand-new replacement laptops"], correct:0, explain:"Containment limits the incident, preventing it from spreading while you respond.", reward:"Containment Sense" },
  { id:"alert-investigation-015", tier:"Beginner", topic:"Alert Investigation", prompt:"Why keep clear notes during an investigation?", options:["To make the report look more polished","To slow the investigation down on purpose","To record actions, findings, and decisions for handoff and review","To delete data once it is no longer needed"], correct:2, explain:"Good notes capture what was done and found, aiding handoffs, reviews, and reports.", reward:"Documentation Sense" },
  { id:"alert-investigation-016", tier:"Beginner", topic:"Alert Investigation", prompt:"When a SOC analyst gets an alert, a key early question is...?", options:["Which team first reported it?","Who originally designed this alert?","How fast is the affected disk?","Is this real, and how serious is it?"], correct:3, explain:"Analysts first ask whether an alert is a genuine threat and how serious it is.", reward:"Analyst Mindset" },
  { id:"alert-investigation-017", tier:"Intermediate", topic:"Alert Investigation", prompt:"During triage, what is a good first question about an alert?", options:["Is this a real threat, and how urgent is it?","What color is the dashboard?","Who designed the logo?","How fast is the CPU?"], correct:0, explain:"Triage starts by judging whether an alert is genuine and how urgent it is.", reward:"Triage Focus" },
  { id:"alert-investigation-018", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is a possible domain admin compromise usually rated high severity?", options:["It generally looks much nicer overall","It could give an attacker broad control over the environment","It adds some color to the dashboard","It helps the server save some power"], correct:1, explain:"Compromise of highly privileged accounts can lead to wide-reaching damage, so it is high severity.", reward:"Severity Sense" },
  { id:"alert-investigation-019", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why are too many false positives a problem for a SOC?", options:["They make the dashboard look pretty","They speed up the whole triage process","They save the company a lot of money","They waste analyst time and can cause real alerts to be missed"], correct:3, explain:"Excess false positives create noise and fatigue, risking that genuine threats are overlooked.", reward:"Signal Clarity" },
  { id:"alert-investigation-020", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should evidence be collected without altering the original where possible?", options:["To save disk","To look neat","To keep it trustworthy and accurate","To speed up"], correct:2, explain:"Preserving originals keeps evidence reliable; working from copies avoids accidental changes.", reward:"Evidence Care" },
  { id:"alert-investigation-021", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is accurate, synchronized time important for timelines?", options:["Reports end up looking much neater","Events from different systems can be correctly sequenced","Servers end up saving more power","The host's CPU runs a bit faster"], correct:1, explain:"Synchronized clocks let you line up events across systems into a correct order.", reward:"Timeline Sense" },
  { id:"alert-investigation-022", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert involves a user account. Which is a useful follow-up question?", options:["What systems and data can that account access?","What is the user's favorite color?","How tall is the user?","What car do they drive?"], correct:0, explain:"Understanding the account's access helps gauge potential impact and scope.", reward:"Scope Focus" },
  { id:"alert-investigation-023", tier:"Intermediate", topic:"Alert Investigation", prompt:"Knowing an affected host is a domain controller changes the response how?", options:["It makes no difference to the response","It actually lowers the priority instead","It raises priority because of the host's critical role","It automatically deletes the alert"], correct:2, explain:"Critical hosts like domain controllers warrant faster, more careful response.", reward:"Host Focus" },
  { id:"alert-investigation-024", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is it suspicious if a document viewer spawns a command shell?", options:["This is completely normal everyday behavior","Doing so helps the host save some power","It simply adds color to the process tree","Document apps rarely launch shells, which hints at malicious activity"], correct:3, explain:"Unusual parent-child chains, like a document app spawning a shell, often indicate an exploit or macro.", reward:"Process Insight" },
  { id:"alert-investigation-025", tier:"Intermediate", topic:"Alert Investigation", prompt:"A process ran with a command line that downloads and executes a file from the internet. Why is this notable?", options:["It can indicate malicious download-and-run behavior","It is always completely safe to ignore","It helps the computer save some power","It just adds color to the log output"], correct:0, explain:"Download-and-execute command lines are a common malware pattern worth investigating.", reward:"Command Insight" },
  { id:"alert-investigation-026", tier:"Intermediate", topic:"Alert Investigation", prompt:"A host is connecting to a rare external IP repeatedly. Why investigate?", options:["It is always perfectly fine to ignore","It could be command-and-control or data exfiltration","It helps the host save some power","It just adds color to the traffic log"], correct:1, explain:"Repeated connections to an unusual destination may indicate C2 or data leaving.", reward:"Connection Insight" },
  { id:"alert-investigation-027", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why look up a suspicious file's hash in a threat intelligence service?", options:["To resize the suspicious file","To rename the suspicious file","To make the file open faster","To see if it is already known to be malicious"], correct:3, explain:"Hash lookups quickly tell you if a file matches known malware.", reward:"Hash Insight" },
  { id:"alert-investigation-028", tier:"Intermediate", topic:"Alert Investigation", prompt:"Which log source would best show a user's login history?", options:["The office printer's job log","An online weather data feed","Authentication or identity logs","A screensaver timeout setting"], correct:2, explain:"Authentication and identity logs record logins, key for investigating account activity.", reward:"Log Source Sense" },
  { id:"alert-investigation-029", tier:"Intermediate", topic:"Alert Investigation", prompt:"When should an analyst typically escalate an incident?", options:["It should essentially never be escalated at all","When it is serious, spreading, or beyond their authority to resolve","Only late on a Friday afternoon shift","Only when the severity is very low"], correct:1, explain:"Escalate when impact, complexity, or authority requirements exceed the analyst's level.", reward:"Escalation Sense" },
  { id:"alert-investigation-030", tier:"Intermediate", topic:"Alert Investigation", prompt:"Which is a good containment question for a compromised laptop?", options:["Should we isolate it from the network to stop spread?","What color is the laptop's case?","How old is the laptop hardware?","Who originally built the laptop?"], correct:0, explain:"Deciding whether to isolate the host is a core containment question.", reward:"Containment Sense" },
  { id:"alert-investigation-031", tier:"Intermediate", topic:"Alert Investigation", prompt:"Which is most useful to record in incident notes?", options:["Today's local weather forecast details","What the analyst had for lunch today","Timestamps of actions, evidence found, and decisions made","Which color the screen currently displays"], correct:2, explain:"Recording actions, evidence, and decisions with times keeps the investigation accountable.", reward:"Documentation Sense" },
  { id:"alert-investigation-032", tier:"Intermediate", topic:"Alert Investigation", prompt:"Which question helps scope an incident?", options:["What color is the alert?","What time is lunch?","How big is the office?","Which users, hosts, and data are involved?"], correct:3, explain:"Identifying affected users, hosts, and data defines the incident's scope.", reward:"Analyst Mindset" },
  { id:"alert-investigation-033", tier:"Advanced", topic:"Alert Investigation", prompt:"Why is consistent triage important across a SOC team?", options:["So alerts are assessed and prioritized the same way regardless of who handles them","Mainly so the SOC can buy and use more screens","In order to deliberately slow the response down","Simply to delete the related evidence afterward"], correct:0, explain:"Consistent triage criteria keep prioritization fair and reliable no matter which analyst responds.", reward:"Triage Focus" },
  { id:"alert-investigation-034", tier:"Beginner", topic:"Alert Investigation", prompt:"Two alerts arrive: one on a test machine, one on a production database. Which is likely higher severity?", options:["The alert on the test machine","The production database alert, due to greater impact","Neither one really matters here","Whichever alert arrived more recently"], correct:1, explain:"Impact on critical production systems usually raises severity over isolated test systems.", reward:"Severity Sense" },
  { id:"alert-investigation-035", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a 'false negative'?", options:["A harmless alert raised by mistake","A routine backup of alert data","A patch applied to a sensor","A real threat that was NOT detected or alerted on"], correct:3, explain:"A false negative is a genuine attack the system failed to catch, which is dangerous.", reward:"Signal Clarity" },
  { id:"alert-investigation-036", tier:"Beginner", topic:"Alert Investigation", prompt:"Which is an example of useful investigation evidence?", options:["Desktop wallpaper currently set","Cooling fan spin speed","Relevant log entries and timestamps","Brand of the keyboard used"], correct:2, explain:"Logs, timestamps, and related artifacts are concrete evidence for an investigation.", reward:"Evidence Care" },
  { id:"alert-investigation-037", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert at 02:14 is followed by data leaving at 02:20. A timeline helps show what?", options:["Which color the screen is currently showing","A likely sequence linking the alert to the data movement","How hot the CPU is currently running","Which font the SOC dashboard uses"], correct:1, explain:"Ordering events reveals likely cause-and-effect links, such as access leading to exfiltration.", reward:"Timeline Sense" },
  { id:"alert-investigation-038", tier:"Beginner", topic:"Alert Investigation", prompt:"If a user's account is compromised, a sensible early step is to...?", options:["Reset the password and review the account's recent activity","Ignore it and simply close the alert","Grant the account even more access","Delete all of the related system logs"], correct:0, explain:"Resetting credentials and reviewing activity limits misuse and reveals what happened.", reward:"Scope Focus" },
  { id:"alert-investigation-039", tier:"Beginner", topic:"Alert Investigation", prompt:"Which detail about an affected host is most useful to an investigation?", options:["The color of its outer case","How much the hardware weighs","Its role, owner, and what it connects to","Which brand sticker is on it"], correct:2, explain:"A host's role, owner, and connections help scope impact and next steps.", reward:"Host Focus" },
  { id:"alert-investigation-040", tier:"Beginner", topic:"Alert Investigation", prompt:"In a process tree, the 'parent' process is the one that...?", options:["Always runs last in the tree","Is the smallest one shown","Uses the least memory overall","Started the child process"], correct:3, explain:"The parent is the process that launched (spawned) the child process.", reward:"Process Insight" },
  { id:"alert-investigation-041", tier:"Beginner", topic:"Alert Investigation", prompt:"An analyst sees a command line that deletes shadow copies (backup snapshots). Why is this a red flag?", options:["Deleting backups is common just before ransomware encryption","Freeing disk space in a harmless way","Making the disk run noticeably faster","Routine cleanup that always happens"], correct:0, explain:"Attackers often delete backup snapshots so victims can't easily recover, a known ransomware precursor.", reward:"Command Insight" },
  { id:"alert-investigation-042", tier:"Beginner", topic:"Alert Investigation", prompt:"Which network detail is useful when investigating a connection?", options:["The color of the network cable","The destination address and port","The temperature of the server room","The size of the attached monitor"], correct:1, explain:"Destination address and port help identify what service or server a host contacted.", reward:"Connection Insight" },
  { id:"alert-investigation-043", tier:"Beginner", topic:"Alert Investigation", prompt:"If two files have the same hash, what does that usually mean?", options:["Their contents are completely different","One of them has been encrypted","One of them is noticeably bigger","Their contents are identical"], correct:3, explain:"Matching hashes indicate identical file contents.", reward:"Hash Insight" },
  { id:"alert-investigation-044", tier:"Beginner", topic:"Alert Investigation", prompt:"Endpoint logs are most useful for seeing what?", options:["The current local weather report","Today's latest stock market prices","What happened on a specific device, like processes and files","Tonight's television show schedules"], correct:2, explain:"Endpoint logs capture device-level activity such as processes, files, and logons.", reward:"Log Source Sense" },
  { id:"alert-investigation-045", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is timely escalation important?", options:["Producing nicer incident reports","Serious incidents need the right people and powers quickly","It deliberately slows the response","Deleting data that is not needed"], correct:1, explain:"Fast escalation brings in the authority and skills needed before damage grows.", reward:"Escalation Sense" },
  { id:"alert-investigation-046", tier:"Beginner", topic:"Alert Investigation", prompt:"Isolating an infected machine from the network mainly helps to do what?", options:["Prevent the threat from reaching other systems","Make the machine run faster","Brighten the machine's screen","Add more storage to the machine"], correct:0, explain:"Network isolation stops the threat from spreading or communicating out.", reward:"Containment Sense" },
  { id:"alert-investigation-047", tier:"Beginner", topic:"Alert Investigation", prompt:"Why are accurate incident notes valuable after an incident ends?", options:["They make the final slides look much nicer","They help the team choose report colors","They support reporting, lessons learned, and similar future cases","They help the servers save some power"], correct:2, explain:"Notes feed post-incident reviews, reporting, and improvements for next time.", reward:"Documentation Sense" },
  { id:"alert-investigation-048", tier:"Beginner", topic:"Alert Investigation", prompt:"A useful analyst question about an alert is 'What...'", options:["brand of chair is in the office?","is the guest Wi-Fi password?","color is painted on the wall?","triggered this, and is it expected?"], correct:3, explain:"Asking what caused the alert and whether it is expected helps separate real threats from noise.", reward:"Analyst Mindset" },
  { id:"alert-investigation-049", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the goal of triaging a flood of alerts?", options:["Focus effort on the alerts that matter most","Ignore every single one of them","Reply to each one with an email","Turn off monitoring altogether"], correct:0, explain:"Triage directs limited analyst time toward the highest-priority alerts.", reward:"Triage Focus" },
  { id:"alert-investigation-050", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should severity consider both likelihood and impact?", options:["Using more colors on the main dashboard display","A serious-impact event that is also likely deserves the highest priority","Slowing the whole triage process down on purpose","Deleting the lowest priority alerts first"], correct:1, explain:"Combining how bad it could be with how likely it is gives a better priority than either alone.", reward:"Severity Sense" },
  { id:"alert-investigation-051", tier:"Intermediate", topic:"Alert Investigation", prompt:"How can tuning detection rules help with false positives?", options:["It deletes the related log files","It hides real attacks from view","It speeds up the host's CPU","It reduces noisy alerts so real threats stand out"], correct:3, explain:"Tuning rules to fit the environment cuts false positives and sharpens focus on real activity.", reward:"Signal Clarity" },
  { id:"alert-investigation-052", tier:"Intermediate", topic:"Alert Investigation", prompt:"What does 'chain of custody' help ensure for evidence?", options:["A noticeably faster Wi-Fi link","A set of nicer report colors","A clear record of who handled evidence and when","More storage for the case files"], correct:2, explain:"Chain of custody documents handling so evidence stays trustworthy and defensible.", reward:"Evidence Care" },
  { id:"alert-investigation-053", tier:"Advanced", topic:"Alert Investigation", prompt:"Why can time zone differences complicate timeline building?", options:["Mixed zones add color to the charts","Logs in different zones can be misordered unless normalized","Different zones speed things up a lot","Separate zones save extra disk space"], correct:1, explain:"Mixed time zones can scramble event order; normalizing to one zone like UTC prevents mistakes.", reward:"Timeline Sense" },
  { id:"alert-investigation-054", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why check whether an affected user holds privileged roles?", options:["Privileged accounts can cause far more damage if misused","It helps the team pick a lunch spot","Changing the desktop wallpaper faster","Slowing the triage queue down a bit"], correct:0, explain:"A compromised admin or privileged user is much higher risk than a standard account.", reward:"Scope Focus" },
  { id:"alert-investigation-055", tier:"Advanced", topic:"Alert Investigation", prompt:"Why map an affected host's network connections during investigation?", options:["To make the network charts look nicer","To help the host save some power","To see where the threat may have spread or communicated","To slow the whole investigation down"], correct:2, explain:"A host's connections can reveal lateral movement targets or C2 destinations.", reward:"Host Focus" },
  { id:"alert-investigation-056", tier:"Intermediate", topic:"Alert Investigation", prompt:"How does a process tree help investigate malware?", options:["It plays a warning sound when triggered","It encrypts all of the affected files","It speeds up the whole system boot","It shows the chain of how a suspicious process was launched"], correct:3, explain:"Tracing the tree reveals the origin and steps that led to a malicious process running.", reward:"Process Insight" },
  { id:"alert-investigation-057", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why might heavily obfuscated command-line text be suspicious?", options:["Attackers often obscure commands to hide intent and evade detection","Obfuscated text simply runs much faster","Encoding the command saves some disk space","It mainly just adds color to the log output"], correct:0, explain:"Obfuscation such as encoding or odd characters is often used to hide malicious command intent.", reward:"Command Insight" },
  { id:"alert-investigation-058", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why compare observed connections against known-bad indicators?", options:["Making the network charts look much nicer","Matches can quickly confirm contact with malicious infrastructure","It helps the host save some extra power","Slowing the whole investigation down a lot"], correct:1, explain:"Checking connections against threat intelligence can confirm malicious contact fast.", reward:"Connection Insight" },
  { id:"alert-investigation-059", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why might a tiny change to a malicious file change its hash completely?", options:["Hashes are completely random values","Hashes simply never change at all","Files cannot ever change at all","A hash is computed from all of the file's contents"], correct:3, explain:"Because hashes depend on the whole file, any change produces a very different hash.", reward:"Hash Insight" },
  { id:"alert-investigation-060", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why are firewall or network logs valuable in an investigation?", options:["They mainly show different colors","They store background music files","They reveal connections and traffic between systems","They pick fonts for the dashboard"], correct:2, explain:"Network logs show who connected to whom, helping trace spread and external contact.", reward:"Log Source Sense" },
  { id:"alert-investigation-061", tier:"Intermediate", topic:"Alert Investigation", prompt:"What information should an analyst include when escalating?", options:["Just the current time of the alert","A clear summary of findings, severity, and evidence so far","Only the analyst's own full name","Nothing at all needs to be included"], correct:1, explain:"A good handoff includes what was found, the severity, and supporting evidence.", reward:"Escalation Sense" },
  { id:"alert-investigation-062", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why balance containment speed against preserving evidence?", options:["Acting too hastily can destroy evidence needed to understand the incident","Picking the right dashboard colors really matters","Mainly to help the affected host save power","Mainly to slow the overall response down"], correct:0, explain:"Aggressive containment like wiping can erase evidence, so weigh both goals.", reward:"Containment Sense" },
  { id:"alert-investigation-063", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should notes distinguish facts from assumptions?", options:["Mainly to add a bit of color","In order to slow the work down","So conclusions are based on evidence, not guesses","Simply to save some disk space"], correct:2, explain:"Separating what is known from what is assumed keeps conclusions reliable.", reward:"Documentation Sense" },
  { id:"alert-investigation-064", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why ask 'has this happened before?' during an investigation?", options:["Mainly to decorate the final case report","To pick a color theme for the dashboard","To help the server save some extra power","Past similar cases can guide the current response and reveal patterns"], correct:3, explain:"Prior similar incidents offer context and proven steps for the current case.", reward:"Analyst Mindset" },
  { id:"alert-investigation-065", tier:"Beginner", topic:"Alert Investigation", prompt:"Triage helps prevent which problem?", options:["Important alerts being buried under less urgent ones","Monitor screens slowly dimming","The CPU slowly heating up","Disk space gradually filling up"], correct:0, explain:"By prioritizing, triage stops critical alerts from getting lost among low-priority noise.", reward:"Triage Focus" },
  { id:"alert-investigation-066", tier:"Beginner", topic:"Alert Investigation", prompt:"A 'low severity' alert generally means what?", options:["Such alerts must always be ignored","Its potential impact is small, so it is lower priority","They are always a false positive","They are the most urgent of all"], correct:1, explain:"Low severity means limited potential impact, so it ranks below more dangerous alerts.", reward:"Severity Sense" },
  { id:"alert-investigation-067", tier:"Advanced", topic:"Alert Investigation", prompt:"Why is it risky to simply suppress an alert type that often false-positives?", options:["Suppression mainly uses more system power","Suppressed alerts tend to look more colorful","Suppression is generally a very slow process","You might also suppress the rare cases when it is a real threat"], correct:3, explain:"Blanket suppression can hide the occasional true positive, so tune carefully rather than mute blindly.", reward:"Signal Clarity" },
  { id:"alert-investigation-068", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why capture volatile data like running processes early in an investigation?", options:["It mainly adds color to reports","It saves the company some money","It can be lost when a system is rebooted or powered off","It is noticeably slower to collect"], correct:2, explain:"Volatile data disappears on reboot or shutdown, so capturing it early preserves key evidence.", reward:"Evidence Care" },
  { id:"alert-investigation-069", tier:"Intermediate", topic:"Alert Investigation", prompt:"What is the benefit of a clear incident timeline for responders?", options:["It mainly makes nicer slides","It guides where to look next and what to contain","It frees up more storage space","It gives the office faster Wi-Fi"], correct:1, explain:"A timeline shows the attack's progression, helping responders focus and contain effectively.", reward:"Timeline Sense" },
  { id:"alert-investigation-070", tier:"Advanced", topic:"Alert Investigation", prompt:"Why review a compromised user's group memberships during investigation?", options:["Groups reveal what the account can access and how far an attacker could reach","Mostly just to decorate the final case report","In order to help the affected host save power","Simply to delete some unneeded old log data"], correct:0, explain:"Group memberships show the account's effective access, helping scope the potential blast radius.", reward:"Scope Focus" },
  { id:"alert-investigation-071", tier:"Beginner", topic:"Alert Investigation", prompt:"Why note the operating system and patch level of an affected host?", options:["Mainly to decorate the final report","To pick nicer colors for the dashboard","To understand likely vulnerabilities and relevant artifacts","To slow the triage process down a bit"], correct:2, explain:"OS and patch state hint at how the host may have been compromised and where to look.", reward:"Host Focus" },
  { id:"alert-investigation-072", tier:"Advanced", topic:"Alert Investigation", prompt:"Why do attackers sometimes inject code into a legitimate process?", options:["Mainly to produce slightly nicer graphics","In order to help the affected host save power","Simply to make the malicious code run faster","To hide malicious activity inside a trusted process and evade detection"], correct:3, explain:"Running inside a trusted process helps malicious code blend in and avoid simple detection.", reward:"Process Insight" },
  { id:"alert-investigation-073", tier:"Advanced", topic:"Alert Investigation", prompt:"Why is capturing the full command line more useful than just the program name?", options:["The arguments reveal intent that the program name alone hides","Arguments simply use up less disk space","Arguments mainly make the log look prettier","Capturing them is generally much faster"], correct:0, explain:"The same program can be benign or malicious depending on its arguments, which the full command line reveals.", reward:"Command Insight" },
  { id:"alert-investigation-074", tier:"Advanced", topic:"Alert Investigation", prompt:"Why can a connection to a legitimate cloud service still be worth examining?", options:["Such cloud traffic never really matters","Attackers sometimes abuse trusted services for C2 or exfiltration","Such cloud traffic just looks colorful","Allowing it saves some extra disk space"], correct:1, explain:"Trusted services can be misused to blend malicious traffic in, so context still matters.", reward:"Connection Insight" },
  { id:"alert-investigation-075", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is hash-only blocking not enough to stop a malware family?", options:["File hashes are completely illegal to use","Computing a file hash is far too slow to do","Files simply cannot ever be blocked at all","Attackers can alter files to produce new hashes that evade the block"], correct:3, explain:"Small changes create new hashes, so signature and behavior detection are needed alongside hashes.", reward:"Hash Insight" },
  { id:"alert-investigation-076", tier:"Advanced", topic:"Alert Investigation", prompt:"Why is it a problem if a key log source has gaps or is not collected?", options:["It saves disk space, which seems good","Stored logs are mostly useless anyway","Missing data can hide attacker activity and break the investigation","It speeds up the host's CPU quite a lot"], correct:2, explain:"Gaps in logging can conceal critical steps, leaving blind spots an attacker can exploit.", reward:"Log Source Sense" },
  { id:"alert-investigation-077", tier:"Advanced", topic:"Alert Investigation", prompt:"Why does a clear escalation path help during a major incident?", options:["A clear path mainly adds color to reports","Everyone knows who to involve and when, avoiding delay and confusion","Having one mainly helps save some power","Defined paths tend to slow everything down"], correct:1, explain:"A defined path ensures the right people are engaged quickly without guesswork.", reward:"Escalation Sense" },
  { id:"alert-investigation-078", tier:"Advanced", topic:"Alert Investigation", prompt:"Why might disabling a compromised account be a containment step?", options:["It stops the attacker from using that account while you investigate","It simply changes the whole dashboard theme","It helps charge the nearby mobile devices","It deletes the existing system backups"], correct:0, explain:"Disabling the account cuts off the attacker's access through it during response.", reward:"Containment Sense" },
  { id:"alert-investigation-079", tier:"Advanced", topic:"Alert Investigation", prompt:"Why can poor or missing incident notes hurt a response?", options:["Poor notes only ever look a bit bad","Skipping notes always saves a lot of time","Responders may repeat work or lose track of findings and decisions","Good notes speed up the affected host CPU"], correct:2, explain:"Without clear notes, teams lose context, duplicate effort, and may miss key findings.", reward:"Documentation Sense" },
  { id:"alert-investigation-080", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why ask 'what is the potential impact?' early in an investigation?", options:["It helps choose dashboard colors","It slows the response down a bit","It picks fonts for the report","It guides how urgently and strongly to respond"], correct:3, explain:"Understanding potential impact shapes the urgency and scale of the response.", reward:"Analyst Mindset" },
  { id:"alert-investigation-081", tier:"Beginner", topic:"Alert Investigation", prompt:"After triage decides an alert is a true positive, what typically happens next?", options:["It moves to deeper investigation or response","It is deleted from the queue","It is ignored and left alone","It is encrypted and archived"], correct:0, explain:"A confirmed true positive proceeds to investigation and, if needed, containment and response.", reward:"Triage Focus" },
  { id:"alert-investigation-082", tier:"Beginner", topic:"Alert Investigation", prompt:"Why can an alert's severity change as an investigation continues?", options:["Analysts simply get bored of the case","New evidence may show greater or smaller impact than first thought","The dashboard colors slowly keep changing","The wall clock just keeps on moving"], correct:1, explain:"As facts emerge, the assessed impact can rise or fall, so severity is updated accordingly.", reward:"Severity Sense" },
  { id:"alert-investigation-083", tier:"Beginner", topic:"Alert Investigation", prompt:"An alert fired because IT ran an approved maintenance script. This is most likely a...?", options:["Real breach","Ransomware","Data theft","False positive"], correct:3, explain:"Expected, authorized activity that triggers an alert is a false positive.", reward:"Signal Clarity" },
  { id:"alert-investigation-084", tier:"Advanced", topic:"Alert Investigation", prompt:"Why might powering off a compromised machine destroy useful evidence?", options:["Shutting down mainly saves some power","Powering off is generally much faster","Volatile memory and active connections are lost on shutdown","It simply looks a lot tidier afterward"], correct:2, explain:"Memory contents and live connections vanish at shutdown, so capture them before powering down if appropriate.", reward:"Evidence Care" },
  { id:"alert-investigation-085", tier:"Beginner", topic:"Alert Investigation", prompt:"A timeline mainly arranges events by what?", options:["Color","Time order","File size","Alphabet"], correct:1, explain:"A timeline orders events chronologically to reconstruct what happened.", reward:"Timeline Sense" },
  { id:"alert-investigation-086", tier:"Beginner", topic:"Alert Investigation", prompt:"An alert involves a service account. Why can that be concerning?", options:["Service accounts often have broad access and may be watched less closely","These accounts simply use up more power","Such accounts tend to look much more colorful","They charge nearby mobile devices much faster"], correct:0, explain:"Service accounts can hold significant access and are sometimes monitored less, making compromise impactful.", reward:"Scope Focus" },
  { id:"alert-investigation-087", tier:"Beginner", topic:"Alert Investigation", prompt:"Two alerts hit the same host within minutes. Why might that matter?", options:["Making the incident charts look much nicer","It helps the affected host save power","Related alerts on one host may indicate a single unfolding incident","Slowing the overall response down a bit"], correct:2, explain:"Multiple alerts on one host close in time can be stages of the same incident worth correlating.", reward:"Host Focus" },
  { id:"alert-investigation-088", tier:"Beginner", topic:"Alert Investigation", prompt:"A process tree mainly helps answer which question?", options:["What color is the process icon?","How big is the system disk?","What time did the host boot?","What launched this process, and what did it launch?"], correct:3, explain:"Process trees clarify what started a process and what it spawned.", reward:"Process Insight" },
  { id:"alert-investigation-089", tier:"Beginner", topic:"Alert Investigation", prompt:"An unusual command line on a server should prompt an analyst to do what?", options:["Investigate what it did and whether it was authorized","Ignore it and quietly close the case","Delete the affected host straight away","Reboot it blindly without checking"], correct:0, explain:"Unexpected commands warrant checking their purpose and whether they were legitimate.", reward:"Command Insight" },
  { id:"alert-investigation-090", tier:"Beginner", topic:"Alert Investigation", prompt:"A server normally talks only to internal systems but now connects to an unknown foreign IP. Why investigate?", options:["Such outbound traffic is always perfectly fine","This deviation from its normal behavior could indicate compromise","Such outbound traffic just looks colorful","Allowing it helps the server save power"], correct:1, explain:"A sudden connection that breaks the host's normal pattern can signal a compromise.", reward:"Connection Insight" },
  { id:"alert-investigation-091", tier:"Advanced", topic:"Alert Investigation", prompt:"Why might analysts also use 'fuzzy' or similarity hashing on malware?", options:["It mainly just looks a bit nicer overall","It is always noticeably faster to run each time","It uses almost no storage space at all","It can match files that are similar but not identical, catching variants"], correct:3, explain:"Similarity hashing groups related variants that exact hashes would miss.", reward:"Hash Insight" },
  { id:"alert-investigation-092", tier:"Beginner", topic:"Alert Investigation", prompt:"A SIEM helps investigations mainly by doing what?", options:["Playing background music for the team","Cooling the host's CPU down a bit","Bringing many log sources together to search and correlate","Printing large posters for the office"], correct:2, explain:"A SIEM centralizes logs so analysts can search and correlate across sources.", reward:"Log Source Sense" },
  { id:"alert-investigation-093", tier:"Beginner", topic:"Alert Investigation", prompt:"Escalating an alert mainly does what?", options:["Deletes it from the alert queue","Gets it to people with more skill or authority","Hides it from the other analysts","Encrypts it before it is stored"], correct:1, explain:"Escalation routes an alert to those better equipped to handle it.", reward:"Escalation Sense" },
  { id:"alert-investigation-094", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is containment usually done before full eradication?", options:["Stopping the spread first limits damage while you plan removal","It simply looks a bit better overall","Helping the affected host save power","Picking colors for the final report"], correct:0, explain:"Containing the threat first prevents further damage while you prepare to fully remove it.", reward:"Containment Sense" },
  { id:"alert-investigation-095", tier:"Beginner", topic:"Alert Investigation", prompt:"Why timestamp each action in incident notes?", options:["Mainly to decorate the final case file","To pick nicer colors for the report","So the sequence of response actions is clear and reviewable","To help the host save some extra power"], correct:2, explain:"Timestamps let others follow exactly when each step happened during the response.", reward:"Documentation Sense" },
  { id:"alert-investigation-096", tier:"Beginner", topic:"Alert Investigation", prompt:"A good closing question for an investigation is...?", options:["What should the team order for dinner?","Which dashboard color should we use next?","Who on the response team is taller?","Is the threat fully contained and the cause understood?"], correct:3, explain:"Before closing, confirm the threat is contained and the root cause is understood.", reward:"Analyst Mindset" },
  { id:"alert-investigation-097", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why might an analyst quickly close many alerts during triage as 'no action'?", options:["Many are benign or known-good, so time is saved for real threats","To deliberately hide the real attacks","Because the alerts are completely random","To delete all of the related log files"], correct:0, explain:"Recognizing benign or expected activity lets analysts dismiss noise and focus on genuine threats.", reward:"Triage Focus" },
  { id:"alert-investigation-098", tier:"Beginner", topic:"Alert Investigation", prompt:"Severity helps a SOC mainly do what?", options:["Pick the desktop wallpaper","Decide which alerts to respond to first","Choose the team's lunch spot","Decide what to name servers"], correct:1, explain:"Severity ranking guides the order in which alerts are investigated and handled.", reward:"Severity Sense" },
  { id:"alert-investigation-099", tier:"Intermediate", topic:"Alert Investigation", prompt:"Before closing an alert as a false positive, an analyst should do what?", options:["Do nothing further about it at all","Simply guess at the most likely cause","Delete all of the related log files","Confirm the activity is truly benign with supporting evidence"], correct:3, explain:"Verify with evidence that the activity is genuinely benign before dismissing it.", reward:"Signal Clarity" },
  { id:"alert-investigation-100", tier:"Beginner", topic:"Alert Investigation", prompt:"Good evidence handling mainly supports what?", options:["Faster gaming performance","Much brighter monitor screens","Reliable conclusions and trustworthy reporting","Bigger storage disks overall"], correct:2, explain:"Careful evidence handling keeps findings credible and reports trustworthy.", reward:"Evidence Care" },
  { id:"alert-investigation-101", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the first goal when investigating a security alert?", options:["Understand what triggered the alert and whether it may represent real risk","Delete the alert as fast as possible","Assume the alert is always a false positive","Disable the detection rule immediately"], correct:0, explain:"The first step is to understand the alert, its evidence, and possible impact.", reward:"Triage Start" },
  { id:"alert-investigation-102", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a true positive alert?", options:["An alert that was created by mistake","An alert that correctly identifies suspicious or malicious activity","An alert with no evidence","An alert that should never be investigated"], correct:1, explain:"A true positive means the alert points to real suspicious or malicious behavior.", reward:"Alert Basics" },
  { id:"alert-investigation-103", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a false positive alert?", options:["An alert that proves compromise","An alert that contains malware","An alert that fires on benign activity","An alert that cannot be closed"], correct:2, explain:"A false positive means the alert matched normal or harmless activity.", reward:"Alert Basics" },
  { id:"alert-investigation-104", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts not close alerts without reviewing evidence?", options:["Closing alerts always creates malware","Alerts cannot be reopened later","Reviewing evidence slows all investigations permanently","Important suspicious activity could be missed"], correct:3, explain:"Evidence review helps avoid dismissing real threats too quickly.", reward:"Evidence First" },
  { id:"alert-investigation-105", tier:"Beginner", topic:"Alert Investigation", prompt:"What does alert severity usually represent?", options:["The potential importance or impact of the alert","The color of the dashboard only","The length of the alert title","The number of letters in the username"], correct:0, explain:"Severity helps prioritize alerts based on possible risk or impact.", reward:"Severity Sense" },
  { id:"alert-investigation-106", tier:"Beginner", topic:"Alert Investigation", prompt:"Why can a low-severity alert still matter?", options:["Low severity always means compromise","It may be part of a larger pattern or affect a critical asset","Low severity alerts cannot be investigated","Low severity alerts never contain evidence"], correct:1, explain:"Low-severity events can become important when correlated with other evidence.", reward:"Triage Context" },
  { id:"alert-investigation-107", tier:"Beginner", topic:"Alert Investigation", prompt:"What is alert triage?", options:["Deleting alerts by age","Changing alert names","Quickly assessing priority, evidence, and next steps","Disabling all noisy detections"], correct:2, explain:"Triage helps decide whether an alert needs deeper investigation or escalation.", reward:"Triage Skill" },
  { id:"alert-investigation-108", tier:"Beginner", topic:"Alert Investigation", prompt:"What is escalation in alert handling?", options:["Changing the dashboard theme","Ignoring the alert until later","Closing the alert without evidence","Sending the case to a higher level or specialist when needed"], correct:3, explain:"Escalation brings in the right expertise or authority for more serious cases.", reward:"Escalation Sense" },
  { id:"alert-investigation-109", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is the affected hostname important in an alert?", options:["It identifies which system may be involved","It replaces all other evidence","It proves the user is malicious","It shows the user's password"], correct:0, explain:"The hostname helps identify the system to investigate and its business context.", reward:"Asset Context" },
  { id:"alert-investigation-110", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is the username important in an alert?", options:["Usernames are only decorative","It helps identify which account may be involved","Usernames prove the alert is false","Usernames replace endpoint logs"], correct:1, explain:"The account involved can help determine scope, impact, and next steps.", reward:"Identity Context" },
  { id:"alert-investigation-111", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is the timestamp important in an alert?", options:["It changes the alert severity automatically","It encrypts the log entry","It helps place the event in a timeline","It deletes old evidence"], correct:2, explain:"Timestamps help correlate events and build an investigation timeline.", reward:"Timeline Sense" },
  { id:"alert-investigation-112", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is the source IP useful in an alert?", options:["It always proves the attacker identity","It replaces all user context","It shows the monitor used by the user","It may show where network activity originated"], correct:3, explain:"Source IP helps identify where traffic or access attempts came from.", reward:"Network Context" },
  { id:"alert-investigation-113", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is the destination IP useful in an alert?", options:["It may show what system or service was contacted","It always proves compromise","It replaces process evidence","It shows the user's password"], correct:0, explain:"Destination IP helps identify the target of network activity.", reward:"Network Context" },
  { id:"alert-investigation-114", tier:"Beginner", topic:"Alert Investigation", prompt:"What is an indicator of compromise?", options:["A dashboard color setting","A clue such as a suspicious IP, domain, file hash, or behavior","A user's lunch break time","A normal helpdesk ticket number"], correct:1, explain:"IOCs are clues that may help identify malicious activity.", reward:"IOC Sense" },
  { id:"alert-investigation-115", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should indicators be used with context?", options:["Indicators are always complete proof","Indicators cannot appear in logs","Indicators may be shared, stale, reused, or benign in some contexts","Indicators replace investigation"], correct:2, explain:"IOCs are useful leads, but they need supporting evidence.", reward:"Triage Context" },
  { id:"alert-investigation-116", tier:"Beginner", topic:"Alert Investigation", prompt:"What is enrichment in alert investigation?", options:["Deleting fields from the alert","Changing alert colors","Closing the alert automatically","Adding extra context such as reputation, asset owner, or user details"], correct:3, explain:"Enrichment adds context that helps analysts make better decisions.", reward:"Enrichment Skill" },
  { id:"alert-investigation-117", tier:"Beginner", topic:"Alert Investigation", prompt:"Why check asset criticality during triage?", options:["Critical systems may increase the priority and impact of an alert","Critical systems cannot be attacked","Asset criticality replaces evidence","Only low-value assets need investigation"], correct:0, explain:"The same activity may be more serious on a sensitive server than on a test device.", reward:"Risk Context" },
  { id:"alert-investigation-118", tier:"Beginner", topic:"Alert Investigation", prompt:"Why check whether the activity is expected for the user or host?", options:["Expected activity always means compromise","It helps distinguish normal behavior from suspicious behavior","Expected activity cannot be logged","It removes the need for timestamps"], correct:1, explain:"Behavior must be judged against what is normal for that user or system.", reward:"Baseline Sense" },
  { id:"alert-investigation-119", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a baseline in alert investigation?", options:["A password reset file","A firewall vendor name","A picture of normal behavior used for comparison","A deleted alert queue"], correct:2, explain:"Baselines help analysts spot deviations from normal behavior.", reward:"Baseline Sense" },
  { id:"alert-investigation-120", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts avoid assuming every alert is malicious?", options:["It prevents them from using logs","It makes every case impossible","It hides all evidence","Normal activity can trigger alerts and needs context before judgment"], correct:3, explain:"Analysts should investigate evidence rather than jump to conclusions.", reward:"Analyst Mindset" },
  { id:"alert-investigation-121", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts avoid assuming every alert is harmless?", options:["Real attacks may initially look small or routine","Harmless alerts never exist","False positives are impossible","It makes dashboards slower"], correct:0, explain:"A calm but serious approach helps prevent missed incidents.", reward:"Analyst Mindset" },
  { id:"alert-investigation-122", tier:"Beginner", topic:"Alert Investigation", prompt:"What should an analyst write in alert notes?", options:["Only 'done' for every alert","What was checked, what was found, and why a decision was made","Nothing, because notes are not useful","Only the alert title copied again"], correct:1, explain:"Good notes explain the investigation and support later review.", reward:"Case Notes" },
  { id:"alert-investigation-123", tier:"Beginner", topic:"Alert Investigation", prompt:"Why are good case notes useful?", options:["They replace logs permanently","They prevent all false positives","They help others understand the decision and continue work if needed","They make alerts disappear faster"], correct:2, explain:"Clear notes support handoff, audit, and learning.", reward:"Case Notes" },
  { id:"alert-investigation-124", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a good reason to reopen or escalate a closed alert?", options:["The dashboard color changed","The alert title was too long","The analyst wants fewer cases","New evidence shows the activity may be more serious"], correct:3, explain:"New evidence can change the conclusion and justify reopening or escalation.", reward:"Evidence First" },
  { id:"alert-investigation-125", tier:"Beginner", topic:"Alert Investigation", prompt:"What is containment?", options:["An action to limit further damage or spread during an incident","A method for changing alert colors","A DNS record type","A normal password reminder"], correct:0, explain:"Containment aims to stop or limit ongoing harmful activity.", reward:"Containment Sense" },
  { id:"alert-investigation-126", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should containment actions be controlled?", options:["Containment can never affect business","Containment can disrupt users, systems, or evidence if done poorly","Containment removes all need for investigation","Containment actions are always reversible"], correct:1, explain:"Containment should balance risk reduction with business and evidence impact.", reward:"Containment Sense" },
  { id:"alert-investigation-127", tier:"Beginner", topic:"Alert Investigation", prompt:"What is evidence preservation?", options:["Changing logs after an incident","Deleting old events to reduce noise","Keeping relevant logs, files, and details available for investigation","Closing all related alerts"], correct:2, explain:"Preserving evidence helps understand what happened and supports response.", reward:"Evidence Handling" },
  { id:"alert-investigation-128", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should logs be collected before some disruptive response actions?", options:["Logs are never useful after collection","Response actions always improve evidence","Logs slow containment permanently","Some actions may remove volatile evidence or change system state"], correct:3, explain:"Collecting evidence first can preserve important details before they disappear.", reward:"Evidence Handling" },
  { id:"alert-investigation-129", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a timeline in an investigation?", options:["An ordered sequence of relevant events","A list of random alert names","A password policy template","A firewall rule backup"], correct:0, explain:"Timelines help analysts understand order, cause, and scope.", reward:"Timeline Sense" },
  { id:"alert-investigation-130", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is event order important?", options:["Event order is only decorative","It helps determine what happened first and how activity progressed","Event order deletes false positives","Event order replaces enrichment"], correct:1, explain:"Correct order helps distinguish cause, effect, and attacker progression.", reward:"Timeline Sense" },
  { id:"alert-investigation-131", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check related alerts?", options:["Related alerts are always duplicates","Related alerts should always be deleted","They may show a larger pattern or connected activity","Related alerts cannot contain evidence"], correct:2, explain:"Multiple alerts can reveal a broader incident chain.", reward:"Correlation Sense" },
  { id:"alert-investigation-132", tier:"Beginner", topic:"Alert Investigation", prompt:"What is correlation in alert investigation?", options:["Changing alert severity randomly","Removing old logs","Adding new users to a case","Connecting related evidence across alerts, logs, users, hosts, or time"], correct:3, explain:"Correlation helps turn isolated clues into a clearer picture.", reward:"Correlation Sense" },
  { id:"alert-investigation-133", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check the detection rule description?", options:["It explains why the alert fired and what behavior it is looking for","It always proves compromise","It replaces all investigation","It shows the user's password"], correct:0, explain:"The rule description helps analysts understand the detection logic.", reward:"Detection Context" },
  { id:"alert-investigation-134", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is the data source important in an alert?", options:["Data sources are only decoration","It tells which logs or telemetry produced the alert","Data sources replace asset inventory","Data sources prevent false positives"], correct:1, explain:"Knowing the source helps analysts judge reliability and what evidence is available.", reward:"Data Source Sense" },
  { id:"alert-investigation-135", tier:"Beginner", topic:"Alert Investigation", prompt:"What should an analyst consider if required logs are missing?", options:["The alert is automatically true","The alert is automatically false","The investigation may have visibility gaps","The system is fully contained"], correct:2, explain:"Missing logs can limit confidence and should be noted.", reward:"Visibility Gap" },
  { id:"alert-investigation-136", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a visibility gap?", options:["A monitor with low brightness","A typo in the alert title","A dashboard with too many colors","Missing or incomplete telemetry needed to understand activity"], correct:3, explain:"Visibility gaps make investigation harder because evidence is incomplete.", reward:"Visibility Gap" },
  { id:"alert-investigation-137", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts identify the affected user or owner?", options:["They can confirm expected behavior or business context","They replace technical evidence","They always caused the alert intentionally","They can delete all logs"], correct:0, explain:"Users and owners can provide context about normal activity and asset purpose.", reward:"Owner Context" },
  { id:"alert-investigation-138", tier:"Beginner", topic:"Alert Investigation", prompt:"What is an alert queue?", options:["A network cable bundle","A list of alerts waiting for review or action","A password storage file","A DNS zone transfer"], correct:1, explain:"Alert queues organize alerts for analysts to triage and investigate.", reward:"SOC Workflow" },
  { id:"alert-investigation-139", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is prioritization needed in an alert queue?", options:["Every alert has identical risk","Prioritization prevents all attacks","Analysts have limited time and should handle higher-risk alerts first","Prioritization deletes evidence"], correct:2, explain:"Prioritization helps focus effort where impact may be highest.", reward:"SOC Workflow" },
  { id:"alert-investigation-140", tier:"Beginner", topic:"Alert Investigation", prompt:"What is alert fatigue?", options:["A network speed test","A password failure","A firewall update","Overload or desensitization caused by too many low-value alerts"], correct:3, explain:"Alert fatigue can reduce analyst attention and response quality.", reward:"Alert Quality" },
  { id:"alert-investigation-141", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should noisy alerts be tuned carefully?", options:["Poor tuning can either hide real threats or overwhelm analysts","Tuning means deleting all detections","Noisy alerts are always malicious","Tuning replaces investigation"], correct:0, explain:"Good tuning balances detection coverage and alert usefulness.", reward:"Alert Quality" },
  { id:"alert-investigation-142", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a duplicate alert?", options:["An alert with malware attached","Another alert about the same or highly similar activity","A false positive by definition","A detection that cannot be closed"], correct:1, explain:"Duplicate alerts may represent the same event or repeated detection of the same behavior.", reward:"SOC Workflow" },
  { id:"alert-investigation-143", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should duplicate alerts still be checked briefly?", options:["Duplicates are always true positives","Duplicates cannot matter","They may show repeated activity, spread, or a larger pattern","They replace incident timelines"], correct:2, explain:"Duplicates may add useful scope or timing context.", reward:"Correlation Sense" },
  { id:"alert-investigation-144", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a case in SOC work?", options:["A computer monitor cover","A type of DNS request","A password reset form","A grouped investigation record containing alerts, evidence, notes, and actions"], correct:3, explain:"Cases organize investigation work and evidence.", reward:"SOC Workflow" },
  { id:"alert-investigation-145", tier:"Beginner", topic:"Alert Investigation", prompt:"Why group related alerts into a case?", options:["It keeps connected evidence and actions together","It hides evidence from analysts","It prevents escalation","It automatically proves compromise"], correct:0, explain:"Grouping related alerts helps analysts understand the full situation.", reward:"SOC Workflow" },
  { id:"alert-investigation-146", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a reasonable closure reason for a false positive?", options:["No reason needed","Activity matched expected business behavior and no suspicious evidence was found","The alert title was boring","The analyst wanted a smaller queue"], correct:1, explain:"Closure notes should explain why the activity was judged benign.", reward:"Case Notes" },
  { id:"alert-investigation-147", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a reasonable closure reason for a true positive?", options:["The alert looked interesting","The dashboard was red","Evidence confirmed suspicious or malicious activity","The user was unavailable"], correct:2, explain:"True-positive closure should be based on evidence, not appearance.", reward:"Evidence First" },
  { id:"alert-investigation-148", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts avoid vague notes like 'checked, ok'?", options:["They make every alert malicious","They prevent the alert from closing","They increase CPU usage","They do not explain what was checked or why the decision was made"], correct:3, explain:"Good notes should support review, handoff, and learning.", reward:"Case Notes" },
  { id:"alert-investigation-149", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the value of a playbook in alert investigation?", options:["It gives repeatable guidance for investigating and responding to common alert types","It replaces analyst thinking completely","It deletes false positives automatically","It prevents all incidents"], correct:0, explain:"Playbooks provide structure while still requiring judgment.", reward:"Playbook Sense" },
  { id:"alert-investigation-150", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should playbooks be updated after lessons learned?", options:["Playbooks never become outdated","Real investigations reveal better checks, gaps, and response improvements","Updates make playbooks impossible to use","Playbooks should only be written once"], correct:1, explain:"Lessons learned improve future investigation quality.", reward:"Lessons Learned" },
  { id:"alert-investigation-151", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert fires for suspicious PowerShell. What should an analyst check?", options:["Only the alert title","Parent process, command line, user, host, script content, and related events","Only the desktop wallpaper","Only whether PowerShell exists"], correct:1, explain:"PowerShell alerts need process, user, command, and timeline context.", reward:"PowerShell Triage" },
  { id:"alert-investigation-152", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is the parent process important in process alerts?", options:["Parent process is always harmless","It changes the hostname automatically","It helps show how the suspicious process was launched","It replaces command-line evidence"], correct:2, explain:"Parent-child process relationships can reveal phishing, scripting, or unusual execution chains.", reward:"Process Tree" },
  { id:"alert-investigation-153", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows Outlook spawning PowerShell. Why is this suspicious?", options:["Outlook should always run PowerShell","PowerShell cannot be used maliciously","Email clients are never involved in attacks","It may indicate phishing, macro execution, or malicious attachment behavior"], correct:3, explain:"Office or email clients spawning scripting tools can indicate initial access activity.", reward:"Phishing Triage" },
  { id:"alert-investigation-154", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked when an alert involves a suspicious command line?", options:["Arguments, encoded content, download behavior, paths, user, and parent process","Only whether the command is long","Only whether the user is online","Only the file icon"], correct:0, explain:"Command-line details often reveal intent and behavior.", reward:"Command Review" },
  { id:"alert-investigation-155", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why are encoded command lines worth reviewing?", options:["Encoding always proves harmless activity","Encoding may hide script content or make commands harder to read","Encoded commands cannot run","Encoding only happens in backups"], correct:1, explain:"Encoding can be legitimate, but it is also commonly used to hide suspicious commands.", reward:"Command Review" },
  { id:"alert-investigation-156", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a process writing to a startup folder. What does this suggest?", options:["A normal DNS query only","A monitor setting change","Possible persistence behavior","A router firmware update"], correct:2, explain:"Startup locations can be abused to run code after reboot or login.", reward:"Persistence Triage" },
  { id:"alert-investigation-157", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why are scheduled task alerts important?", options:["Scheduled tasks cannot run code","Scheduled tasks are only used by printers","Scheduled tasks are never logged","They can be used for persistence or automated execution"], correct:3, explain:"Scheduled tasks can be legitimate or abused, so context matters.", reward:"Persistence Triage" },
  { id:"alert-investigation-158", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked in a suspicious scheduled task alert?", options:["Task name, action, command, user, creation time, and related process activity","Only the task icon","Only the keyboard language","Only the alert color"], correct:0, explain:"Scheduled task details help determine whether it is expected or malicious.", reward:"Persistence Triage" },
  { id:"alert-investigation-159", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows many failed logins for one account. What should be considered?", options:["Only the user's profile picture","Possible password guessing, stale credentials, or misconfigured service","A successful software update","A DNS cache refresh"], correct:1, explain:"Repeated failures can indicate attack attempts or broken authentication sources.", reward:"Login Triage" },
  { id:"alert-investigation-160", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows one IP trying many usernames. What pattern may this indicate?", options:["Normal single-user activity","A firewall firmware update","Password spraying or account enumeration","A DNS zone transfer"], correct:2, explain:"One source trying many accounts is suspicious for spraying or enumeration.", reward:"Spray Triage" },
  { id:"alert-investigation-161", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked after a successful login following many failures?", options:["Only whether the password was short","Only whether the alert is red","Only the browser theme","Whether the login came from the same source and what activity followed"], correct:3, explain:"A success after many failures may indicate compromise and should be scoped.", reward:"Login Triage" },
  { id:"alert-investigation-162", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is MFA context important in login alerts?", options:["MFA success, failure, fatigue, or bypass signs help judge account risk","MFA removes the need for investigation","MFA events cannot be logged","MFA always proves the user is safe"], correct:0, explain:"MFA details provide important identity-security context.", reward:"MFA Triage" },
  { id:"alert-investigation-163", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert says 'impossible travel.' What should an analyst check?", options:["Only the user's password length","Locations, timing, VPN use, device trust, and user history","Only the alert title","Only whether the user has email"], correct:1, explain:"Impossible-travel alerts need identity, location, device, and VPN context.", reward:"Identity Triage" },
  { id:"alert-investigation-164", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why can VPN use complicate location-based alerts?", options:["VPNs prevent all attacks","VPNs remove authentication logs","VPN egress IPs may make location appear different from the user's physical location","VPNs always prove compromise"], correct:2, explain:"VPN infrastructure can make sign-in geography misleading.", reward:"VPN Context" },
  { id:"alert-investigation-165", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a new inbox forwarding rule. Why is this suspicious?", options:["Inbox rules cannot affect email","Forwarding rules always indicate normal work","Email alerts are never security-relevant","Attackers may use forwarding rules to monitor or exfiltrate mail"], correct:3, explain:"Mailbox forwarding can be abused after account compromise.", reward:"Email Triage" },
  { id:"alert-investigation-166", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked in a mailbox rule alert?", options:["Rule creator, destination, rule conditions, timing, sign-in history, and mailbox activity","Only the rule color","Only the user's desktop background","Only whether the user has a phone"], correct:0, explain:"Mailbox rule investigation needs rule details and account activity context.", reward:"Email Triage" },
  { id:"alert-investigation-167", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a suspicious file hash. What should an analyst do?", options:["Assume the file is malicious forever","Check reputation, file path, signer, prevalence, execution, and related behavior","Delete all files with similar names","Ignore the alert if the filename looks normal"], correct:1, explain:"File hash alerts need reputation and behavior context.", reward:"File Triage" },
  { id:"alert-investigation-168", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why can filename alone be weak evidence?", options:["Filenames are always unique","Filenames cannot be logged","Attackers can rename files and legitimate files can have suspicious names","Filenames prove the file hash"], correct:2, explain:"Filename is only one clue and should be combined with hash, signer, path, and behavior.", reward:"File Triage" },
  { id:"alert-investigation-169", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is file path important in malware-related alerts?", options:["Paths always prove a file is safe","Paths cannot be changed","Paths replace all hash checks","Unusual paths can indicate suspicious staging, execution, or persistence"], correct:3, explain:"Malware often runs from suspicious or user-writable locations.", reward:"File Triage" },
  { id:"alert-investigation-170", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked when an alert involves a downloaded file?", options:["Download source, user, file hash, path, execution, and related network activity","Only the filename length","Only whether the user likes the website","Only the alert color"], correct:0, explain:"Downloaded-file alerts need web, file, process, and user context.", reward:"Download Triage" },
  { id:"alert-investigation-171", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a process contacting a rare domain. What context helps?", options:["Only the domain length","Process name, command line, user, host role, DNS history, reputation, and timing","Only whether the domain has vowels","Only the system wallpaper"], correct:1, explain:"Rare-domain alerts are best triaged with process, host, and reputation context.", reward:"Network Triage" },
  { id:"alert-investigation-172", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is process-to-network correlation useful?", options:["It replaces all investigation","It hides evidence from analysts","It links network activity to the program that generated it","It disables TLS encryption"], correct:2, explain:"Knowing which process made a connection helps explain intent.", reward:"Correlation Sense" },
  { id:"alert-investigation-173", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows regular outbound connections every minute. What could this indicate?", options:["Only a local keyboard event","Only a DNS record update","A normal password reset","Possible beaconing or automated check-in behavior"], correct:3, explain:"Regular timing can indicate automated communication such as beaconing.", reward:"Beaconing Triage" },
  { id:"alert-investigation-174", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be reviewed in a suspected beaconing alert?", options:["Destination, interval, process, host, user, volume, and whether behavior is expected","Only packet color","Only keyboard language","Only alert title"], correct:0, explain:"Beaconing triage needs timing, destination, process, and host context.", reward:"Beaconing Triage" },
  { id:"alert-investigation-175", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows large outbound data transfer. What should be considered?", options:["Large transfer always proves normal backup","Possible exfiltration, backup, update, or expected business transfer","Large transfer cannot be logged","Outbound data is never risky"], correct:1, explain:"Large outbound transfer needs destination, source, timing, and data context.", reward:"Exfil Triage" },
  { id:"alert-investigation-176", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts check whether a data transfer was expected?", options:["Expected transfers are always malicious","Transfer expectation removes all evidence","It helps distinguish business activity from possible exfiltration","Expected transfers cannot be large"], correct:2, explain:"Business context is essential for judging data movement.", reward:"Business Context" },
  { id:"alert-investigation-177", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be done if an alert appears to involve a critical server?", options:["Ignore it because servers are always noisy","Close it if the username is familiar","Delete old logs to reduce confusion","Raise priority and check impact, owner, and related activity"], correct:3, explain:"Critical assets increase potential impact and deserve careful triage.", reward:"Risk Context" },
  { id:"alert-investigation-178", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should alerts involving domain controllers receive special attention?", options:["Domain controllers are central to identity and authentication","Domain controllers cannot be attacked","Domain controllers only store wallpapers","Domain controllers replace all firewalls"], correct:0, explain:"Compromise of identity infrastructure can have major impact.", reward:"Critical Asset" },
  { id:"alert-investigation-179", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows suspicious registry modification. What should be checked?", options:["Only the registry key color","Key path, value, process, user, timestamp, and whether it supports persistence or defense evasion","Only whether the user has email","Only the alert ID"], correct:1, explain:"Registry changes need path, process, and purpose context.", reward:"Registry Triage" },
  { id:"alert-investigation-180", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why are autorun registry keys important?", options:["They only store DNS records","They prevent all malware","They can be used to launch programs automatically for persistence","They are always harmless"], correct:2, explain:"Autorun locations can be abused to execute malware after login or reboot.", reward:"Persistence Triage" },
  { id:"alert-investigation-181", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked in a suspicious service creation alert?", options:["Only the service display color","Only whether the user has a mailbox","Only the screen resolution","Service name, binary path, creator, timestamp, account, and related process"], correct:3, explain:"Service creation can be legitimate administration or persistence/lateral movement.", reward:"Service Triage" },
  { id:"alert-investigation-182", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is service binary path important?", options:["It shows what executable the service runs","It always proves the service is safe","It replaces user context","It deletes the service automatically"], correct:0, explain:"The binary path reveals what code the service will execute.", reward:"Service Triage" },
  { id:"alert-investigation-183", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows endpoint protection disabled. Why is this important?", options:["Endpoint protection can never be disabled","Disabling protection may indicate defense evasion or risky misconfiguration","Protection status does not matter","It always means a scheduled update completed"], correct:1, explain:"Security-tool tampering is a common defense-evasion concern.", reward:"Defense Evasion" },
  { id:"alert-investigation-184", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked in a security-tool tampering alert?", options:["Only the alert color","Only whether the device has internet","Actor, process, command, policy, timestamp, and whether the change was approved","Only the user's profile picture"], correct:2, explain:"Tampering alerts require evidence about who changed what and why.", reward:"Defense Evasion" },
  { id:"alert-investigation-185", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts look for activity before and after the alert time?", options:["Only the exact alert event matters","Before and after events are always unrelated","Logs outside the alert time should be deleted","Surrounding events can reveal cause, execution chain, and impact"], correct:3, explain:"The alert is often only one point in a larger timeline.", reward:"Timeline Sense" },
  { id:"alert-investigation-186", tier:"Advanced", topic:"Alert Investigation", prompt:"A suspicious PowerShell alert has an encoded command and external download. What is the best next step?", options:["Decode or inspect the command, identify download source, process chain, user, host, and follow-on activity","Close it because PowerShell is built into Windows","Delete the alert without notes","Assume it is safe if the user is an admin"], correct:0, explain:"Encoded download behavior needs command, network, process, and user context.", reward:"PowerShell Triage" },
  { id:"alert-investigation-187", tier:"Advanced", topic:"Alert Investigation", prompt:"A user has impossible travel, MFA fatigue prompts, and a new mailbox forwarding rule. What does this suggest?", options:["A normal software update","Possible account compromise with persistence or mail exfiltration","A harmless DNS issue","A normal password expiration"], correct:1, explain:"Combined identity and mailbox signals increase compromise concern.", reward:"Identity Correlation" },
  { id:"alert-investigation-188", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should analysts map alert evidence to an attack timeline?", options:["Timelines make every alert true","Timelines replace containment","They help show progression from initial access to later actions","Timelines hide uncertainty"], correct:2, explain:"Attack timelines clarify sequence, scope, and response priorities.", reward:"Timeline Sense" },
  { id:"alert-investigation-189", tier:"Advanced", topic:"Alert Investigation", prompt:"An alert shows admin tool usage from an unusual host. What context matters most?", options:["Only whether the tool is signed","Only the screen resolution","Only whether the hostname is short","User role, host role, timing, approval, command details, and target systems"], correct:3, explain:"Legitimate tools can be abused, so context determines risk.", reward:"Living-off-land Triage" },
  { id:"alert-investigation-190", tier:"Advanced", topic:"Alert Investigation", prompt:"Why can living-off-the-land activity be difficult to triage?", options:["Legitimate tools can be used for both normal administration and malicious activity","Built-in tools never appear in attacks","Living-off-the-land activity cannot be logged","Only malware creates alerts"], correct:0, explain:"The same tool may be normal or suspicious depending on context and behavior.", reward:"Living-off-land Triage" },
  { id:"alert-investigation-191", tier:"Advanced", topic:"Alert Investigation", prompt:"A detection fires on credential dumping behavior. What should responders prioritize?", options:["Only checking the alert title","Confirm evidence, isolate if needed, identify affected accounts, and scope follow-on activity","Changing the dashboard color","Ignoring it if the host is online"], correct:1, explain:"Credential access can enable wider compromise and needs urgent scoping.", reward:"Credential Triage" },
  { id:"alert-investigation-192", tier:"Advanced", topic:"Alert Investigation", prompt:"Why is scoping important after a confirmed true positive?", options:["Scoping prevents all future attacks","Scoping is only useful for false positives","It identifies affected users, hosts, data, and follow-on activity","Scoping deletes evidence"], correct:2, explain:"Scoping tells responders how large the incident may be.", reward:"Scope Control" },
  { id:"alert-investigation-193", tier:"Advanced", topic:"Alert Investigation", prompt:"A host shows malware execution, outbound beaconing, and lateral SMB connections. What does this suggest?", options:["Only normal web browsing","Only a DHCP issue","Only a printer problem","A possible multi-stage compromise requiring containment and scoping"], correct:3, explain:"Multiple stages across host, network, and lateral movement raise incident severity.", reward:"Incident Correlation" },
  { id:"alert-investigation-194", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should analysts preserve original evidence when escalating?", options:["Escalated teams need reliable source material to verify findings and continue response","Evidence should be rewritten before escalation","Escalation replaces evidence collection","Original evidence slows the process without value"], correct:0, explain:"Preserved evidence supports continuity, accuracy, and later review.", reward:"Evidence Handling" },
  { id:"alert-investigation-195", tier:"Advanced", topic:"Alert Investigation", prompt:"What should be included in a high-quality escalation note?", options:["Only 'please check'","Summary, evidence, timeline, affected assets, actions taken, uncertainty, and requested help","Only the alert name","Only a screenshot of the dashboard"], correct:1, explain:"Escalation notes should help the next responder act quickly and accurately.", reward:"Escalation Sense" },
  { id:"alert-investigation-196", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should containment decisions consider business impact?", options:["Business impact never matters in security","Containment always has no side effects","Some containment actions can disrupt critical services or users","Business context makes attacks harmless"], correct:2, explain:"Containment should reduce risk without unnecessary damage.", reward:"Containment Sense" },
  { id:"alert-investigation-197", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should alert tuning be based on evidence?", options:["Tuning based on annoyance alone may hide real threats or create blind spots","Tuning should always disable noisy rules","Evidence is only needed for legal teams","Tuning cannot affect detection coverage"], correct:0, explain:"Tuning should reduce noise while preserving important detection value.", reward:"Detection Quality" },
  { id:"alert-investigation-198", tier:"Advanced", topic:"Alert Investigation", prompt:"A detection creates many alerts for expected admin activity. What is a mature response?", options:["Delete the rule immediately","Tune with context such as approved admin tools, hosts, users, and change windows","Ignore all alerts from admins forever","Remove all logging"], correct:1, explain:"Good tuning preserves suspicious coverage while reducing known-benign noise.", reward:"Detection Quality" },
  { id:"alert-investigation-199", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should lessons learned be captured after major alert investigations?", options:["Lessons learned replace incident response","They improve detections, playbooks, logging, training, and controls","They prove no future alert will happen","They are only useful for managers"], correct:2, explain:"Lessons learned turn investigation experience into better future defense.", reward:"Lessons Learned" },
  { id:"alert-investigation-200", tier:"Advanced", topic:"Alert Investigation", prompt:"What is the best mindset for alert investigation?", options:["Close as many alerts as possible without notes","Assume tools are always right","Treat every alert as impossible to solve","Follow evidence, preserve context, document decisions, and escalate when needed"], correct:3, explain:"Good alert investigation is evidence-driven, structured, and accountable.", reward:"Analyst Mindset" },
  { id:"alert-investigation-201", tier:"Beginner", topic:"Alert Investigation", prompt:"What should an analyst do when opening a new alert?", options:["Read the alert details and identify the key evidence fields","Immediately close it to reduce queue size","Assume the alert title tells the whole story","Disable the rule before checking anything"], correct:0, explain:"Start by understanding what the alert says, what evidence it includes, and what it may mean.", reward:"Triage Start" },
  { id:"alert-investigation-202", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should an analyst check the alert source?", options:["The alert source is only decorative","It helps determine which tool, log source, or detection created the alert","It proves the alert is malicious","It replaces investigation notes"], correct:1, explain:"Knowing where the alert came from helps judge available evidence and reliability.", reward:"Data Source Sense" },
  { id:"alert-investigation-203", tier:"Beginner", topic:"Alert Investigation", prompt:"What does 'affected asset' mean in an alert?", options:["The SOC dashboard theme","The analyst assigned to the queue","The system, account, or resource involved in the alert","The vendor name of the SIEM"], correct:2, explain:"The affected asset is what may have been targeted, misused, or compromised.", reward:"Asset Context" },
  { id:"alert-investigation-204", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts identify the affected asset owner?", options:["Owners always caused the alert","Owners can delete all alerts","Owners replace technical evidence","Owners can help confirm expected activity and business impact"], correct:3, explain:"Asset owners can provide useful business and operational context.", reward:"Owner Context" },
  { id:"alert-investigation-205", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a suspicious activity timeline?", options:["A chronological view of events related to the alert","A random list of usernames","A password reset template","A firewall vendor comparison"], correct:0, explain:"A timeline helps show how events unfolded before and after the alert.", reward:"Timeline Sense" },
  { id:"alert-investigation-206", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check events before the alert time?", options:["Earlier events may show what caused or led to the alert","Earlier events are never relevant","Earlier events automatically prove compromise","Earlier events should always be deleted"], correct:1, explain:"Activity before the alert can reveal initial access, execution, or user actions.", reward:"Timeline Sense" },
  { id:"alert-investigation-207", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check events after the alert time?", options:["Later events are always harmless","Later events replace the original alert","Later events may show impact, spread, or follow-on activity","Later events cannot be logged"], correct:2, explain:"Follow-on activity helps determine whether the alert is isolated or part of a larger incident.", reward:"Timeline Sense" },
  { id:"alert-investigation-208", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the purpose of asking 'what changed?' during investigation?", options:["To avoid looking at evidence","To blame the user immediately","To close the alert faster","To identify recent actions that may explain the alert"], correct:3, explain:"Recent changes can explain benign activity or reveal suspicious behavior.", reward:"Change Context" },
  { id:"alert-investigation-209", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check whether the activity was approved?", options:["Approved change records can explain expected behavior","Approval always proves the activity is safe","Unapproved activity is always malicious","Approval removes the need for logs"], correct:0, explain:"Change records and approvals help distinguish expected work from suspicious activity.", reward:"Change Context" },
  { id:"alert-investigation-210", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a change window?", options:["A browser popup during login","A planned time period when changes are expected or allowed","A DNS record type","A password expiration reminder"], correct:1, explain:"Change windows help analysts judge whether activity matches approved maintenance.", reward:"Change Context" },
  { id:"alert-investigation-211", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is user confirmation sometimes useful?", options:["Users can always prove alerts are false","Users replace log evidence","Users may confirm whether they performed or expected the activity","Users can delete the alert queue"], correct:2, explain:"User confirmation can add context, but it should be combined with technical evidence.", reward:"User Context" },
  { id:"alert-investigation-212", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should user confirmation not be the only evidence?", options:["Users always lie","Users cannot remember anything","Users should never be contacted","Accounts can be compromised, and users may be mistaken"], correct:3, explain:"A compromised account may perform actions the real user did not authorize.", reward:"Evidence First" },
  { id:"alert-investigation-213", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful question when an alert involves a file?", options:["What is the file hash, path, signer, source, and behavior?","What color is the file icon?","How many letters are in the filename?","Does the alert title sound scary?"], correct:0, explain:"File alerts need multiple clues, not filename alone.", reward:"File Triage" },
  { id:"alert-investigation-214", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is file signer information useful?", options:["It always proves a file is safe","It can help identify whether software is signed by a known publisher","It replaces all malware analysis","It deletes suspicious files"], correct:1, explain:"Signer information is useful context, though signed files can still be abused.", reward:"File Triage" },
  { id:"alert-investigation-215", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is file prevalence useful?", options:["Rare files are always malicious","Common files are always safe","Rare or unusual files may deserve closer review","Prevalence disables malware execution"], correct:2, explain:"How common a file is can help prioritize review, but it is not proof by itself.", reward:"File Triage" },
  { id:"alert-investigation-216", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful question when an alert involves a process?", options:["Does the process have a nice icon?","Is the filename short?","Is the process using a common font?","What launched it, what command ran, and what did it do next?"], correct:3, explain:"Process context includes parent process, command line, user, and follow-on behavior.", reward:"Process Tree" },
  { id:"alert-investigation-217", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is the command line important in process alerts?", options:["It can show what the process was instructed to do","It always proves the process is malicious","It replaces endpoint logs","It only shows the hostname"], correct:0, explain:"Command-line arguments often reveal intent, targets, scripts, or suspicious flags.", reward:"Command Review" },
  { id:"alert-investigation-218", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a parent process?", options:["A process that has no user","The process that launched another process","A process that only runs on servers","A process that cannot be logged"], correct:1, explain:"Parent process context helps explain how a process started.", reward:"Process Tree" },
  { id:"alert-investigation-219", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a child process?", options:["A process used only by children","A process that cannot access files","A process launched by another process","A process with no executable path"], correct:2, explain:"Child processes can show follow-on activity from a suspicious parent.", reward:"Process Tree" },
  { id:"alert-investigation-220", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is parent-child process context useful?", options:["It replaces all network evidence","It proves every alert is true","It hides suspicious activity","It helps reveal unusual execution chains"], correct:3, explain:"Unusual process chains can show phishing, script execution, or living-off-the-land behavior.", reward:"Process Tree" },
  { id:"alert-investigation-221", tier:"Beginner", topic:"Alert Investigation", prompt:"What should an analyst check when an alert involves a URL?", options:["Domain, path, reputation, user, process, time, and related downloads","Only whether the URL is long","Only whether it contains numbers","Only whether it uses lowercase letters"], correct:0, explain:"URL alerts need web, user, process, and reputation context.", reward:"URL Triage" },
  { id:"alert-investigation-222", tier:"Beginner", topic:"Alert Investigation", prompt:"Why can a URL path be useful?", options:["URL paths always prove compromise","The path may reveal the resource requested, download name, or suspicious endpoint","URL paths replace DNS logs","URL paths cannot be logged"], correct:1, explain:"The path can show what content or endpoint was accessed.", reward:"URL Triage" },
  { id:"alert-investigation-223", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check whether a domain is newly registered?", options:["New domains are always safe","Old domains are always malicious","New domains may be used in phishing, malware, or temporary infrastructure","Domain age replaces investigation"], correct:2, explain:"Domain age is useful context, not final proof.", reward:"DNS Investigation" },
  { id:"alert-investigation-224", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful question when an alert involves DNS?", options:["What keyboard did the user use?","What color is the DNS record?","Can DNS replace endpoint logs?","Which host queried which domain, when, and how often?"], correct:3, explain:"DNS investigation needs host, domain, timing, and frequency context.", reward:"DNS Investigation" },
  { id:"alert-investigation-225", tier:"Beginner", topic:"Alert Investigation", prompt:"Why are repeated DNS queries useful to review?", options:["They may show beaconing, tunneling, malware activity, or broken software","DNS queries are never security-relevant","Repeated queries always mean normal browsing","DNS frequency cannot be measured"], correct:0, explain:"Frequency and pattern can help identify suspicious or automated behavior.", reward:"DNS Investigation" },
  { id:"alert-investigation-226", tier:"Beginner", topic:"Alert Investigation", prompt:"What should an analyst do when evidence is incomplete?", options:["Pretend the evidence is complete","Document the gap and avoid overstating confidence","Close the case without notes","Delete the alert source"], correct:1, explain:"Visibility gaps should be noted so conclusions remain honest and reviewable.", reward:"Visibility Gap" },
  { id:"alert-investigation-227", tier:"Beginner", topic:"Alert Investigation", prompt:"What does 'confidence' mean in investigation notes?", options:["The analyst's favorite tool","How certain the analyst is based on available evidence","The alert color brightness","The number of alerts in the queue"], correct:2, explain:"Confidence should reflect the strength and completeness of the evidence.", reward:"Evidence First" },
  { id:"alert-investigation-228", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts avoid overstating conclusions?", options:["Strong conclusions are never needed","Overstating makes evidence disappear","It makes alerts impossible to close","Weak evidence can lead to wrong decisions if presented as certain"], correct:3, explain:"Accurate wording protects investigation quality and decision-making.", reward:"Analyst Mindset" },
  { id:"alert-investigation-229", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the purpose of an investigation checklist?", options:["To make sure important steps are not forgotten","To replace all analyst judgment","To delete false positives automatically","To hide uncertainty"], correct:0, explain:"Checklists support consistency while still allowing judgment.", reward:"Playbook Sense" },
  { id:"alert-investigation-230", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should playbooks not be followed blindly?", options:["Playbooks are always wrong","Every case has context, and analysts must adapt steps to the evidence","Playbooks prevent all escalation","Playbooks remove the need for logs"], correct:1, explain:"Playbooks guide work, but real investigations need judgment.", reward:"Playbook Sense" },
  { id:"alert-investigation-231", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful outcome of a completed alert investigation?", options:["No notes and no evidence","Only a closed ticket number","A clear decision, supporting evidence, actions taken, and next steps if needed","A deleted alert history"], correct:2, explain:"A completed investigation should be understandable and defensible.", reward:"Case Notes" },
  { id:"alert-investigation-232", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts record actions taken during an investigation?", options:["Actions do not matter after closure","Recording actions slows the SOC permanently","Actions should be hidden from other teams","It supports accountability, handoff, and later review"], correct:3, explain:"Action history helps others understand what was done and why.", reward:"Case Notes" },
  { id:"alert-investigation-233", tier:"Beginner", topic:"Alert Investigation", prompt:"What does 'scope' mean in an investigation?", options:["The extent of affected users, systems, data, and activity","The color of the alert dashboard","The length of the detection rule name","The number of monitors in the SOC"], correct:0, explain:"Scope describes how far the suspicious activity may have reached.", reward:"Scope Control" },
  { id:"alert-investigation-234", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is scoping important?", options:["Scoping deletes false positives","It helps determine impact and what response actions are needed","Scoping replaces containment","Scoping proves every alert is severe"], correct:1, explain:"Response depends on how many assets, accounts, or data sources are affected.", reward:"Scope Control" },
  { id:"alert-investigation-235", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a related host in an investigation?", options:["A host with the same screen resolution","A host that is always safe","A host that appears connected to the alert through traffic, login, process, or file activity","A host without any logs"], correct:2, explain:"Related hosts can expand or clarify investigation scope.", reward:"Correlation Sense" },
  { id:"alert-investigation-236", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a related account in an investigation?", options:["An account with the same first letter","An account that never logs in","A deleted browser profile","An account connected by shared activity, access, authentication, or suspicious behavior"], correct:3, explain:"Related accounts may show spread, misuse, or shared compromise.", reward:"Identity Context" },
  { id:"alert-investigation-237", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check whether credentials may be exposed?", options:["Credential exposure can lead to follow-on access and wider compromise","Credentials are never reused","Credentials cannot be abused after an alert","Credential checks replace all containment"], correct:0, explain:"Credential risk can change severity and response actions.", reward:"Credential Triage" },
  { id:"alert-investigation-238", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a follow-on activity?", options:["A dashboard refresh","Activity that happens after the initial alert and may show impact or progression","A firewall name change","A normal keyboard shortcut"], correct:1, explain:"Follow-on activity helps reveal whether the alert led to further actions.", reward:"Timeline Sense" },
  { id:"alert-investigation-239", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check whether an alert repeats across multiple hosts?", options:["Repeating alerts are always harmless","Only the first alert matters","Multiple hosts may indicate spread, campaign activity, or common misconfiguration","Repeated alerts cannot be grouped"], correct:2, explain:"Repeated alerts can reveal scope and pattern.", reward:"Correlation Sense" },
  { id:"alert-investigation-240", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful question when many hosts trigger the same alert?", options:["Do all hosts have the same desktop wallpaper?","Can the alerts be deleted together?","Are the hostnames short enough?","Is this a common benign cause, a deployment issue, or spreading malicious activity?"], correct:3, explain:"Multiple alerts need pattern analysis before conclusion.", reward:"Correlation Sense" },
  { id:"alert-investigation-241", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts know the business function of a system?", options:["Business function helps judge expected behavior and potential impact","Business function replaces logs","Business function always proves innocence","Business function disables alerts"], correct:0, explain:"A database server, kiosk, laptop, and domain controller have different normal behavior and risk.", reward:"Business Context" },
  { id:"alert-investigation-242", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a critical asset?", options:["Any device with a keyboard","A system, account, or data store whose compromise could have high impact","A system with the longest hostname","A closed alert"], correct:1, explain:"Critical assets deserve higher attention because impact may be greater.", reward:"Risk Context" },
  { id:"alert-investigation-243", tier:"Beginner", topic:"Alert Investigation", prompt:"Why can the same alert have different priority on different assets?", options:["Priority is random","Severity colors are different per monitor","Business impact and expected behavior can differ by asset","Alert IDs decide everything"], correct:2, explain:"Context changes risk; suspicious behavior on a critical server may matter more.", reward:"Risk Context" },
  { id:"alert-investigation-244", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts consider data sensitivity?", options:["Sensitive data cannot be stolen","Sensitive data makes alerts false positive","Sensitive data removes the need for scoping","Exposure or misuse of sensitive data can increase impact"], correct:3, explain:"Data sensitivity affects severity, notification, containment, and response decisions.", reward:"Risk Context" },
  { id:"alert-investigation-245", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a reasonable next step after confirming malicious activity?", options:["Escalate or begin response according to procedure","Delete all related logs","Mark it false positive","Ignore it if the user is busy"], correct:0, explain:"Confirmed malicious activity should follow incident response procedures.", reward:"Escalation Sense" },
  { id:"alert-investigation-246", tier:"Beginner", topic:"Alert Investigation", prompt:"What should be avoided after confirming malicious activity?", options:["Preserving evidence","Making uncontrolled changes that destroy evidence or disrupt business unnecessarily","Documenting findings","Escalating to the right team"], correct:1, explain:"Response actions should be controlled, documented, and evidence-aware.", reward:"Evidence Handling" },
  { id:"alert-investigation-247", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts know when to ask for help?", options:["Asking for help is never allowed","It proves the analyst failed","Some cases need specialist knowledge or authority","It closes the alert automatically"], correct:2, explain:"Escalation and collaboration are part of mature SOC work.", reward:"Escalation Sense" },
  { id:"alert-investigation-248", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a handoff in alert investigation?", options:["Deleting the case after shift end","Changing the alert title","Turning off the detection rule","Passing the case to another person with enough notes and evidence to continue"], correct:3, explain:"Good handoffs prevent context loss between analysts or teams.", reward:"Case Notes" },
  { id:"alert-investigation-249", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should handoff notes be clear?", options:["The next analyst needs to understand status, evidence, actions, and open questions","Clear notes make all alerts true positives","Notes replace all logs","Notes prevent every future incident"], correct:0, explain:"Clear handoff notes keep investigations moving accurately.", reward:"Case Notes" },
  { id:"alert-investigation-250", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a good habit at the end of an alert investigation?", options:["Leave the case with no conclusion","Document the decision, evidence, and any recommended improvements","Delete related evidence","Disable the detection quietly"], correct:1, explain:"Final notes should explain what happened and what should happen next.", reward:"Case Notes" },
  { id:"alert-investigation-251", tier:"Intermediate", topic:"Alert Investigation", prompt:"A suspicious process alert has no command line field. What should the analyst note?", options:["The alert is automatically false positive","There is a visibility gap, and other evidence should be used to compensate","The process cannot be suspicious","The alert should be deleted"], correct:1, explain:"Missing fields reduce confidence and should be documented.", reward:"Visibility Gap" },
  { id:"alert-investigation-252", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a process launched from a temp directory. Why is that worth review?", options:["Temp directories are always malicious","Only system files can execute","User-writable temp paths are often abused for staging or execution","Temp paths cannot be logged"], correct:2, explain:"Execution from temporary or user-writable paths can be suspicious.", reward:"File Triage" },
  { id:"alert-investigation-253", tier:"Intermediate", topic:"Alert Investigation", prompt:"A signed binary is used with suspicious arguments. What should an analyst do?", options:["Ignore it because signed binaries are always safe","Delete the binary from every host","Review the arguments, parent process, user, and behavior","Assume it is impossible to abuse signed tools"], correct:2, explain:"Legitimate signed tools can be abused with suspicious command lines.", reward:"Living-off-land Triage" },
  { id:"alert-investigation-254", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is 'known good tool' not enough to close an alert?", options:["Known tools cannot run commands","Attackers may abuse legitimate tools for malicious purposes","Known tools are never logged","Tool names prove user intent"], correct:1, explain:"Living-off-the-land activity often uses normal tools in abnormal ways.", reward:"Living-off-land Triage" },
  { id:"alert-investigation-255", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows certutil downloading a file. Why might this be suspicious?", options:["Certutil is always malware","Certutil can be abused as a built-in download or encoding tool","Certutil cannot access networks","Certutil only changes wallpapers"], correct:1, explain:"Built-in tools used for downloads or decoding should be reviewed in context.", reward:"Living-off-land Triage" },
  { id:"alert-investigation-256", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows rundll32 executing from a strange path. What should be checked?", options:["Only whether rundll32 is a Windows binary","DLL path, command line, parent process, user, and related file/network behavior","Only the alert color","Only the computer model"], correct:1, explain:"Rundll32 is legitimate but can execute malicious DLLs.", reward:"Process Triage" },
  { id:"alert-investigation-257", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows mshta launching a remote URL. What is a likely concern?", options:["A normal DHCP renewal","Only a printer driver update","Script execution from remote content","A harmless screen setting"], correct:2, explain:"Mshta can be abused to execute script content and should be investigated.", reward:"Script Triage" },
  { id:"alert-investigation-258", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should analysts check when Office launches a scripting tool?", options:["Only whether Office is installed","Only whether the document has a long name","Only the user's email signature","Possible macro, attachment, document source, child process, and command line"], correct:3, explain:"Office spawning scripts can indicate phishing or malicious document execution.", reward:"Phishing Triage" },
  { id:"alert-investigation-259", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a suspicious browser download. What should be reviewed?", options:["URL, referrer, file hash, user, execution, and reputation","Only the browser icon","Only whether the user likes the website","Only the file extension"], correct:0, explain:"Browser-download alerts need web, file, user, and process context.", reward:"Download Triage" },
  { id:"alert-investigation-260", tier:"Intermediate", topic:"Alert Investigation", prompt:"A user reports they opened a suspicious attachment. What should be checked?", options:["Only the email subject length","Email headers, sender, attachment hash, execution, child processes, and affected host","Only whether the user is embarrassed","Only the message font"], correct:1, explain:"Phishing attachment triage combines email, file, process, and endpoint evidence.", reward:"Phishing Triage" },
  { id:"alert-investigation-261", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why are email headers useful in phishing investigations?", options:["They always prove the sender is legitimate","They replace endpoint evidence","They can show routing, sender authentication, and origin clues","They delete phishing links"], correct:2, explain:"Headers can help analyze sender authenticity and message path.", reward:"Phishing Triage" },
  { id:"alert-investigation-262", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a user clicked a suspicious link. What should be checked next?", options:["Only whether the link is blue","Only the user's browser theme","Only whether the URL is short","Visited URL, redirects, downloaded files, credential entry, and follow-on activity"], correct:3, explain:"Link-click triage should determine what happened after the click.", reward:"Phishing Triage" },
  { id:"alert-investigation-263", tier:"Intermediate", topic:"Alert Investigation", prompt:"A suspicious login alert involves a new device. What context matters?", options:["Device trust, location, MFA result, user history, and activity after login","Only the device wallpaper","Only whether the username is short","Only the alert ID"], correct:0, explain:"New-device logins need identity and device context.", reward:"Identity Triage" },
  { id:"alert-investigation-264", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts review activity after a suspicious login?", options:["Activity after login cannot matter","It shows whether the account accessed data, changed settings, or established persistence","It replaces the login evidence","It proves the login was safe"], correct:1, explain:"Post-login behavior helps determine impact and scope.", reward:"Identity Triage" },
  { id:"alert-investigation-265", tier:"Intermediate", topic:"Alert Investigation", prompt:"A suspicious login is followed by OAuth app consent. What is a concern?", options:["OAuth app consent is always harmless","OAuth consent cannot grant access","A malicious or risky app may gain persistent access to data","OAuth apps cannot be logged"], correct:2, explain:"App consent can create delegated access that persists beyond the initial login.", reward:"OAuth Triage" },
  { id:"alert-investigation-266", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked in an OAuth app consent alert?", options:["Only the app logo","Only the user's display name","Only whether the alert is high severity","App permissions, publisher, user, consent time, accessed data, and sign-in context"], correct:3, explain:"OAuth investigation needs permission and activity context.", reward:"OAuth Triage" },
  { id:"alert-investigation-267", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts check newly created admin accounts?", options:["New admin accounts may indicate privilege escalation or persistence","Admin accounts are always safe","New accounts cannot log in","Admin creation is never logged"], correct:0, explain:"Unexpected admin creation is high-risk and should be investigated.", reward:"Privilege Triage" },
  { id:"alert-investigation-268", tier:"Intermediate", topic:"Alert Investigation", prompt:"A role assignment alert grants high privilege to a user. What should be checked?", options:["Only the user's profile picture","Who granted it, approval reason, timing, target role, and follow-on activity","Only whether the username is long","Only the dashboard color"], correct:1, explain:"Privilege changes need approval and activity context.", reward:"Privilege Triage" },
  { id:"alert-investigation-269", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why are privilege changes important after a suspicious login?", options:["Privilege changes cannot affect security","Privilege changes are always automatic","They may show escalation or attacker persistence","They remove all need for containment"], correct:2, explain:"Attackers may increase access after compromising an account.", reward:"Privilege Triage" },
  { id:"alert-investigation-270", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked after detecting possible credential dumping?", options:["Only the alert title","Only whether the user is online","Only DNS cache entries","Affected host, process, user, dumped material risk, and subsequent authentication activity"], correct:3, explain:"Credential dumping can lead to wider compromise and requires scoping.", reward:"Credential Triage" },
  { id:"alert-investigation-271", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should responders look for lateral movement after credential access?", options:["Stolen credentials may be used to access other systems","Credential access cannot lead to movement","Lateral movement only happens before login","It replaces malware analysis"], correct:0, explain:"Credential theft often enables attackers to move through an environment.", reward:"Lateral Movement" },
  { id:"alert-investigation-272", tier:"Intermediate", topic:"Alert Investigation", prompt:"What network evidence may support lateral movement?", options:["Only one public website visit","Internal RDP, SMB, WinRM, SSH, or authentication activity between hosts","Only browser bookmarks","Only monitor brightness"], correct:1, explain:"Internal administrative or file-sharing connections can indicate movement.", reward:"Lateral Movement" },
  { id:"alert-investigation-273", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is unusual service creation on a remote host suspicious?", options:["Services cannot execute code","Remote services always mean patching","It may indicate lateral movement or persistence","Service names prove legitimacy"], correct:2, explain:"Attackers may create services remotely to execute code on another host.", reward:"Service Triage" },
  { id:"alert-investigation-274", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked in a remote execution alert?", options:["Only the hostname length","Only whether the user has email","Only the alert color","Source host, target host, user, command, tool used, and authentication context"], correct:3, explain:"Remote execution needs source, target, identity, and command context.", reward:"Lateral Movement" },
  { id:"alert-investigation-275", tier:"Intermediate", topic:"Alert Investigation", prompt:"A ransomware-like alert fires on many file renames. What should be checked quickly?", options:["Host isolation needs, affected paths, process, user, file count, backups, and spread indicators","Only the file extension color","Only whether the user is at lunch","Only if the file names are short"], correct:0, explain:"Mass file changes can be high impact and need fast scoping and containment decisions.", reward:"Ransomware Triage" },
  { id:"alert-investigation-276", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why are backup status and scope important in ransomware triage?", options:["Backups cannot help recovery","Backups affect recovery options and business impact","Backups prove the alert is false","Backups delete ransomware automatically"], correct:1, explain:"Backup availability changes response and recovery planning.", reward:"Ransomware Triage" },
  { id:"alert-investigation-277", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked when an alert involves mass file deletion?", options:["Only whether the filename is interesting","Only the user's wallpaper","Process, user, target paths, volume, timing, and whether deletion was expected","Only DNS records"], correct:2, explain:"Mass deletion can be malicious, accidental, or administrative, depending on context.", reward:"Destruction Triage" },
  { id:"alert-investigation-278", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts avoid immediate deletion of suspicious files before collection?", options:["Suspicious files are always harmless","Deleting files improves evidence quality","Files cannot be analyzed later anyway","Evidence such as hash, metadata, and sample content may be needed"], correct:3, explain:"Preserving evidence can support deeper analysis and response.", reward:"Evidence Handling" },
  { id:"alert-investigation-279", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why is endpoint isolation a high-impact action?", options:["It can disrupt user work or services while helping stop spread","It always has no side effects","It deletes malware automatically","It replaces investigation notes"], correct:0, explain:"Isolation can be useful but should be controlled and documented.", reward:"Containment Sense" },
  { id:"alert-investigation-280", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be done before isolating a critical server when possible?", options:["Ignore the alert","Assess business impact, preserve evidence if possible, and get proper approval","Delete the server logs","Disable all monitoring"], correct:1, explain:"Critical assets require careful containment decisions.", reward:"Containment Sense" },
  { id:"alert-investigation-281", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should containment actions be documented?", options:["Documentation prevents all attacks","Containment actions are never reviewed","It records what changed, why, when, and by whom","Documentation replaces rollback"], correct:2, explain:"Containment records support accountability and later recovery.", reward:"Case Notes" },
  { id:"alert-investigation-282", tier:"Intermediate", topic:"Alert Investigation", prompt:"What is a rollback plan in alert response?", options:["A plan to undo or reverse a response action if needed","A plan to delete all alerts","A password reset list only","A rule that prevents escalation"], correct:0, explain:"Rollback planning reduces risk from containment or remediation actions.", reward:"Rollback Sense" },
  { id:"alert-investigation-283", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts separate confirmed facts from hypotheses?", options:["Hypotheses are always false","It keeps investigation reasoning honest and prevents guesses from becoming conclusions","Facts make reports too long","Confirmed facts should not be documented"], correct:1, explain:"Facts and hypotheses serve different purposes in analysis.", reward:"Analyst Mindset" },
  { id:"alert-investigation-284", tier:"Intermediate", topic:"Alert Investigation", prompt:"What is a hypothesis in an investigation?", options:["A deleted alert","A confirmed fact","A guess or explanation to test against evidence","A firewall rule"], correct:2, explain:"Hypotheses guide investigation but must be tested.", reward:"Analyst Mindset" },
  { id:"alert-investigation-285", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts document uncertainty?", options:["Uncertainty makes the case useless","Uncertainty proves the analyst failed","Uncertainty should be hidden","It shows what still needs validation and how confident the conclusion is"], correct:3, explain:"Uncertainty helps future reviewers understand remaining risk.", reward:"Evidence First" },
  { id:"alert-investigation-286", tier:"Advanced", topic:"Alert Investigation", prompt:"A phishing alert includes link click, credential entry, and successful login from a new location. What should be prioritized?", options:["Treat as likely account compromise, revoke sessions if appropriate, reset credentials, and scope activity","Close it because link clicks are common","Only block the URL and ignore the account","Delete the email and take no further action"], correct:0, explain:"Credential entry followed by suspicious login suggests account compromise risk.", reward:"Phishing Response" },
  { id:"alert-investigation-287", tier:"Advanced", topic:"Alert Investigation", prompt:"Why is it risky to tune out all alerts from administrator accounts?", options:["Administrators cannot be compromised","Admin activity is always safe","Admin accounts are high-value and may be abused for major impact","Admin accounts never appear in logs"], correct:2, explain:"Admin activity needs context, not blanket suppression.", reward:"Detection Quality" },
  { id:"alert-investigation-288", tier:"Advanced", topic:"Alert Investigation", prompt:"A malware alert is followed by domain admin login from the same host. What does this suggest?", options:["Only a normal update","Only a DNS cache refresh","A harmless false positive","Possible credential compromise or privilege escalation requiring urgent scoping"], correct:3, explain:"Malware plus privileged authentication can indicate serious compromise.", reward:"Incident Correlation" },
  { id:"alert-investigation-289", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should analysts correlate EDR, identity, DNS, and proxy logs?", options:["Each source provides different evidence about process, user, destination, and behavior","Correlation makes all alerts false","One log source always tells the whole story","Correlation replaces containment"], correct:0, explain:"Multi-source correlation builds a stronger investigation picture.", reward:"Correlation Sense" },
  { id:"alert-investigation-290", tier:"Advanced", topic:"Alert Investigation", prompt:"An alert shows a rare process making outbound connections. What is the best investigation path?", options:["Only check IP reputation","Review process lineage, command line, file reputation, destination, user, and host role","Close it because outbound traffic is normal","Delete the process without collecting evidence"], correct:1, explain:"Rare process network activity needs host, file, process, and destination context.", reward:"Network Triage" },
  { id:"alert-investigation-291", tier:"Advanced", topic:"Alert Investigation", prompt:"Why is attack-chain thinking useful in alert investigation?", options:["It helps connect separate clues into stages like access, execution, persistence, and impact","It replaces all evidence collection","It proves every alert is part of an attack","It is only useful for red teams"], correct:0, explain:"Attack-chain thinking helps analysts reason about progression and missing evidence.", reward:"Attack Chain" },
  { id:"alert-investigation-292", tier:"Advanced", topic:"Alert Investigation", prompt:"A case has weak evidence but high possible impact. What is a mature response?", options:["Close it immediately because evidence is weak","Escalate or investigate further while clearly documenting uncertainty and risk","Ignore possible impact","Delete the alert to avoid panic"], correct:1, explain:"High-impact possibilities may justify more investigation even with uncertainty.", reward:"Risk Context" },
  { id:"alert-investigation-293", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should containment sometimes happen before full root-cause analysis?", options:["Root cause never matters","Containment should always destroy evidence","Ongoing harm may need to be stopped while deeper analysis continues","Containment always proves compromise"], correct:2, explain:"Response may need to reduce active risk while preserving enough evidence where possible.", reward:"Containment Sense" },
  { id:"alert-investigation-294", tier:"Advanced", topic:"Alert Investigation", prompt:"What is the danger of focusing only on the first alert in a case?", options:["The first alert is always wrong","It may miss earlier initial access or later impact activity","First alerts cannot contain evidence","Only the last alert matters"], correct:1, explain:"The first observed alert may not be the first attacker action.", reward:"Timeline Sense" },
  { id:"alert-investigation-295", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should analysts identify the earliest known suspicious activity?", options:["It helps estimate dwell time, initial access, and scope","Earliest activity is always false positive","It replaces eradication","It prevents all future alerts"], correct:0, explain:"Earliest-known activity helps determine how long the issue may have existed.", reward:"Timeline Sense" },
  { id:"alert-investigation-296", tier:"Advanced", topic:"Alert Investigation", prompt:"Why is dwell time important?", options:["It measures how long suspicious or malicious activity may have existed before detection","It is the time a dashboard takes to load","It is only a password setting","It deletes old logs"], correct:0, explain:"Longer dwell time can increase scope and impact.", reward:"Timeline Sense" },
  { id:"alert-investigation-297", tier:"Advanced", topic:"Alert Investigation", prompt:"What should analysts do if a detection has no clear explanation?", options:["Document the gap and review detection logic, fields, and examples with detection owners","Close all alerts from that rule forever","Assume the detection is useless","Ignore the missing explanation"], correct:0, explain:"Unclear detections should be improved so analysts can triage effectively.", reward:"Detection Quality" },
  { id:"alert-investigation-298", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should false-positive findings feed back into detection engineering?", options:["They help tune logic, add context, and reduce future noise without losing coverage","False positives should be hidden","Detection engineers do not need feedback","False positives prove detection is impossible"], correct:0, explain:"SOC feedback improves detection quality over time.", reward:"Lessons Learned" },
  { id:"alert-investigation-299", tier:"Advanced", topic:"Alert Investigation", prompt:"What should be reviewed after a missed true positive?", options:["Only the analyst's typing speed","Telemetry gaps, rule logic, thresholds, data quality, and playbook coverage","Only the alert color","Whether the case title was long enough"], correct:1, explain:"Missed detections reveal where visibility or logic needs improvement.", reward:"Detection Quality" },
  { id:"alert-investigation-300", tier:"Advanced", topic:"Alert Investigation", prompt:"What is a mature final step after a serious alert investigation?", options:["Delete the case to reduce clutter","Avoid discussing what happened","Capture lessons learned and improve playbooks, detections, logging, and controls","Assume the same issue will never happen again"], correct:2, explain:"Serious investigations should improve future defensive capability.", reward:"Lessons Learned" },
  { id:"alert-investigation-301", tier:"Beginner", topic:"Alert Investigation", prompt:"What should an analyst do when an alert contains unfamiliar terminology?", options:["Look up or clarify the meaning before making a decision","Close the alert because unfamiliar terms are not useful","Assume the alert is always malicious","Delete the detection rule"], correct:0, explain:"Understanding the alert language helps avoid wrong conclusions.", reward:"Triage Start" },
  { id:"alert-investigation-302", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check the alert description?", options:["It replaces all evidence","It explains what behavior the detection is trying to identify","It always proves compromise","It removes the need for notes"], correct:1, explain:"The description helps analysts understand why the alert exists.", reward:"Detection Context" },
  { id:"alert-investigation-303", tier:"Beginner", topic:"Alert Investigation", prompt:"What does alert context help an analyst decide?", options:["The color of the SOC dashboard","Whether logs should be deleted","Whether activity is expected, suspicious, or needs escalation","Whether the keyboard is working"], correct:2, explain:"Context helps turn raw alert data into an informed decision.", reward:"Triage Context" },
  { id:"alert-investigation-304", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check whether the alert is part of a known incident?", options:["Known incidents never matter","Known incidents should be ignored","It makes the alert automatically false positive","It may belong to existing scope, containment, or response work"], correct:3, explain:"Related alerts may already be part of an active investigation.", reward:"Correlation Sense" },
  { id:"alert-investigation-305", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful first question for any alert?", options:["What happened, where, when, and to whom?","How fast can I close this?","Can I disable the rule now?","Is the dashboard color nice?"], correct:0, explain:"Basic event facts are the foundation of triage.", reward:"Triage Skill" },
  { id:"alert-investigation-306", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts identify the detection category?", options:["Categories always prove the alert is malicious","It helps choose the right investigation path or playbook","Categories replace evidence","Categories are only for reporting charts"], correct:1, explain:"Different alert types need different checks.", reward:"Playbook Sense" },
  { id:"alert-investigation-307", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a security playbook used for?", options:["Changing alert colors","Deleting duplicate alerts","Guiding repeatable investigation and response steps","Replacing all analyst judgment"], correct:2, explain:"Playbooks provide structure but still require reasoning.", reward:"Playbook Sense" },
  { id:"alert-investigation-308", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should playbooks include decision points?", options:["Decision points make alerts impossible to close","Decision points remove all evidence","Decision points always increase noise","They help analysts decide when to close, continue, contain, or escalate"], correct:3, explain:"Decision points make playbooks practical instead of just lists of tasks.", reward:"Playbook Sense" },
  { id:"alert-investigation-309", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check whether the affected system is online?", options:["System status can affect evidence collection and response options","Offline systems are always safe","Online systems cannot be compromised","System status replaces log review"], correct:0, explain:"Knowing whether the system is reachable helps plan next steps.", reward:"Asset Context" },
  { id:"alert-investigation-310", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check host role?", options:["Host role is only decorative","Expected behavior differs between workstations, servers, and critical systems","Host role proves innocence","Host role deletes false positives"], correct:1, explain:"Context changes depending on what the system is used for.", reward:"Asset Context" },
  { id:"alert-investigation-311", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check whether a host is managed?", options:["Managed hosts cannot be attacked","Unmanaged hosts are always malicious","Managed status affects visibility, control, and response options","Managed status replaces incident response"], correct:2, explain:"Managed systems usually have better logging and response controls.", reward:"Asset Context" },
  { id:"alert-investigation-312", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should unknown assets be investigated carefully?", options:["Unknown assets cannot communicate","Unknown assets are always safe","Unknown assets should be ignored","They may be unauthorized, unmanaged, or poorly monitored"], correct:3, explain:"Unknown assets can create security and visibility gaps.", reward:"Asset Inventory" },
  { id:"alert-investigation-313", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the value of checking recent user activity?", options:["It helps determine whether the alert matches expected user behavior","It proves the user is malicious","It replaces endpoint logs","It deletes suspicious events"], correct:0, explain:"Recent activity can explain or deepen concern about an alert.", reward:"User Context" },
  { id:"alert-investigation-314", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check whether a user is privileged?", options:["Privilege never affects impact","Privileged accounts can cause greater impact if compromised","Privileged users cannot trigger false positives","Privilege removes the need for MFA"], correct:1, explain:"Privileged accounts increase potential risk and response priority.", reward:"Risk Context" },
  { id:"alert-investigation-315", tier:"Beginner", topic:"Alert Investigation", prompt:"What does 'business impact' mean in alert investigation?", options:["The alert's font size","The vendor that created the alert","How the activity could affect users, services, data, or operations","The number of dashboards open"], correct:2, explain:"Business impact helps prioritize and choose response actions.", reward:"Business Context" },
  { id:"alert-investigation-316", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check if an alert affects sensitive data?", options:["Sensitive data cannot be accessed","Sensitive data makes all alerts false positive","Sensitive data disables logging","Exposure of sensitive data can increase severity and response requirements"], correct:3, explain:"Data sensitivity changes risk and escalation needs.", reward:"Risk Context" },
  { id:"alert-investigation-317", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful way to handle uncertain alerts?", options:["Document uncertainty and continue checking evidence","Pretend the answer is certain","Close immediately without notes","Delete related logs"], correct:0, explain:"Uncertainty is normal; it should be documented and reduced with evidence.", reward:"Analyst Mindset" },
  { id:"alert-investigation-318", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts avoid emotional reactions to alerts?", options:["Emotions prove compromise","Calm analysis reduces rushed conclusions and mistakes","Emotional reactions improve evidence quality","Alerts cannot be serious"], correct:1, explain:"Good investigations are evidence-driven, not panic-driven.", reward:"Analyst Mindset" },
  { id:"alert-investigation-319", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful note when closing an alert as benign?", options:["Closed","Looks fine","Evidence checked and why the activity was expected or harmless","No idea"], correct:2, explain:"Closure notes should be clear enough for someone else to understand.", reward:"Case Notes" },
  { id:"alert-investigation-320", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts avoid copying raw sensitive data into case notes?", options:["Case notes cannot contain text","Sensitive data may be exposed to people who can view the case","Notes are never searched","Sensitive data makes alerts false positive"], correct:1, explain:"Notes should include enough context without unnecessarily spreading sensitive data.", reward:"Data Care" },
  { id:"alert-investigation-321", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a good way to reference sensitive evidence in notes?", options:["Paste all secrets directly","Share passwords with the whole team","Describe where evidence is stored and summarize safely","Remove all context from the case"], correct:2, explain:"Sensitive evidence should be referenced safely and stored appropriately.", reward:"Evidence Handling" },
  { id:"alert-investigation-322", tier:"Beginner", topic:"Alert Investigation", prompt:"Why is chain of custody important for some evidence?", options:["It tracks how evidence was collected, handled, and preserved","It changes alert severity automatically","It replaces all investigation notes","It deletes duplicate alerts"], correct:0, explain:"Chain of custody supports evidence integrity and trust.", reward:"Evidence Handling" },
  { id:"alert-investigation-323", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a screenshot useful for in an investigation?", options:["Replacing all logs permanently","Capturing visible evidence or state at a point in time","Proving every alert is malicious","Disabling user accounts"], correct:1, explain:"Screenshots can support notes, but logs and source data are usually still needed.", reward:"Evidence Handling" },
  { id:"alert-investigation-324", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should screenshots be handled carefully?", options:["They cannot contain sensitive information","They are always public evidence","They may contain names, emails, internal URLs, tokens, or customer data","They replace all logs"], correct:2, explain:"Screenshots may reveal sensitive details and should be shared carefully.", reward:"Data Care" },
  { id:"alert-investigation-325", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the purpose of assigning an alert owner?", options:["To know who is responsible for investigating or coordinating the case","To hide the alert from everyone else","To make the alert true positive","To delete the alert automatically"], correct:0, explain:"Ownership prevents confusion and duplicated effort.", reward:"SOC Workflow" },
  { id:"alert-investigation-326", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should alerts have status values like open, in progress, or closed?", options:["Status values make alerts impossible to reopen","They show where the case is in the workflow","Status values replace evidence","They prove the alert is benign"], correct:1, explain:"Status helps coordinate work and queue management.", reward:"SOC Workflow" },
  { id:"alert-investigation-327", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a service-level agreement in SOC work?", options:["A DNS record for services","A firewall rule template","An expected response or handling time for work such as alerts","A malware family name"], correct:2, explain:"SLAs help define response expectations and priorities.", reward:"SOC Workflow" },
  { id:"alert-investigation-328", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should higher-priority alerts be handled faster?", options:["They are always false positives","They need fewer notes","They contain shorter titles","They may represent greater risk or impact"], correct:3, explain:"Priority helps allocate limited analyst time.", reward:"Severity Sense" },
  { id:"alert-investigation-329", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check if an alert is recurring?", options:["Recurring alerts may indicate repeated activity, noise, or unresolved root cause","Recurring alerts are always harmless","Recurring alerts cannot be tuned","Recurring alerts should always be deleted"], correct:0, explain:"Repeated alerts can show patterns or detection-quality issues.", reward:"Alert Quality" },
  { id:"alert-investigation-330", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a suppression rule?", options:["A rule that creates more alerts","A rule that hides or reduces alerts under defined conditions","A firewall that blocks all traffic","A password reset method"], correct:1, explain:"Suppression can reduce noise but must be used carefully.", reward:"Alert Quality" },
  { id:"alert-investigation-331", tier:"Beginner", topic:"Alert Investigation", prompt:"Why can alert suppression be risky?", options:["It may hide real suspicious activity if conditions are too broad","It always improves detection","It prevents all false positives without downside","It makes evidence stronger"], correct:0, explain:"Suppression should be scoped and reviewed to avoid blind spots.", reward:"Detection Quality" },
  { id:"alert-investigation-332", tier:"Beginner", topic:"Alert Investigation", prompt:"What is detection tuning?", options:["Changing monitor brightness","Deleting all detection rules","Making all alerts low priority","Adjusting detection logic to improve signal and reduce noise"], correct:3, explain:"Tuning improves detection usefulness while preserving coverage.", reward:"Detection Quality" },
  { id:"alert-investigation-333", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts report detection issues?", options:["Feedback helps improve rules, fields, thresholds, and playbooks","Detection issues should be hidden","Rules cannot be improved","Reporting issues proves the analyst failed"], correct:0, explain:"SOC feedback improves detection engineering over time.", reward:"Lessons Learned" },
  { id:"alert-investigation-334", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a detection gap?", options:["A keyboard shortcut","A missing or weak detection for activity defenders care about","A password expiration warning","A normal dashboard refresh"], correct:1, explain:"Detection gaps show where monitoring may need improvement.", reward:"Visibility Gap" },
  { id:"alert-investigation-335", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should detection gaps be documented?", options:["They are always harmless","They make alerts disappear","They help prioritize new logging, detections, or controls","They prevent all incidents"], correct:2, explain:"Documented gaps can drive security improvements.", reward:"Lessons Learned" },
  { id:"alert-investigation-336", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a useful lesson from false positives?", options:["All false-positive alerts should be ignored forever","False positives mean detection is impossible","False positives should never be mentioned","They can reveal where context, tuning, or documentation should improve"], correct:3, explain:"False positives are useful feedback when handled constructively.", reward:"Lessons Learned" },
  { id:"alert-investigation-337", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts understand normal maintenance activity?", options:["Maintenance can trigger alerts and should be distinguished from suspicious behavior","Maintenance always means compromise","Maintenance cannot be logged","Maintenance replaces change control"], correct:0, explain:"Expected maintenance can look suspicious without context.", reward:"Change Context" },
  { id:"alert-investigation-338", tier:"Beginner", topic:"Alert Investigation", prompt:"What should an analyst check if an alert occurs during a maintenance window?", options:["Whether the activity matches the approved change","Only the alert color","Whether the user has a nice hostname","Nothing, because all maintenance is safe"], correct:0, explain:"A maintenance window explains timing, but activity still needs to match the approved work.", reward:"Change Context" },
  { id:"alert-investigation-339", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts avoid blaming users in notes?", options:["Blaming users improves security","Notes should stay factual and evidence-based","User behavior is never relevant","Blame replaces containment"], correct:1, explain:"Professional notes focus on evidence, not personal blame.", reward:"Case Notes" },
  { id:"alert-investigation-340", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a professional way to document a user mistake?", options:["Use insults to make the issue clear","Hide the issue completely","Describe the action and evidence neutrally","Delete the case notes"], correct:2, explain:"Neutral language keeps documentation useful and respectful.", reward:"Case Notes" },
  { id:"alert-investigation-341", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should an analyst check if a device is shared?", options:["Shared devices may make user attribution less straightforward","Shared devices are always compromised","Shared devices cannot produce alerts","Shared devices remove need for logs"], correct:0, explain:"Shared devices can complicate who performed an action.", reward:"User Context" },
  { id:"alert-investigation-342", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts check if an account is a service account?", options:["Service accounts are always malicious","Service accounts may perform automated activity that differs from human behavior","Service accounts cannot be compromised","Service accounts have no permissions"], correct:1, explain:"Service accounts need different baseline expectations and controls.", reward:"Identity Context" },
  { id:"alert-investigation-343", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a suspicious sign for a service account?", options:["It runs on its normal schedule","It uses approved automation","It suddenly performs interactive logins or unusual access","It has an owner listed"], correct:2, explain:"Service accounts should have predictable behavior; unusual interactive use may be suspicious.", reward:"Identity Context" },
  { id:"alert-investigation-344", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should service accounts have owners?", options:["Owners make accounts immune to compromise","Owners remove the need for passwords","Owners prevent all alerts","Owners help confirm purpose, expected behavior, and access needs"], correct:3, explain:"Ownership supports investigation and access review.", reward:"Identity Context" },
  { id:"alert-investigation-345", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a good final check before closing an alert?", options:["Confirm the decision is supported by evidence and notes","Check only whether the alert title is short","Delete related logs","Ignore related alerts"], correct:0, explain:"Closure should be evidence-based and documented.", reward:"Case Notes" },
  { id:"alert-investigation-346", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should analysts review alert quality over time?", options:["Alert quality never changes","It helps identify noisy rules, missed detections, and training needs","It replaces incident response","It prevents all future attacks"], correct:1, explain:"Trend review improves the SOC process.", reward:"Alert Quality" },
  { id:"alert-investigation-347", tier:"Beginner", topic:"Alert Investigation", prompt:"What is a good sign of mature alert handling?", options:["No case notes are written","Every alert is closed instantly","Decisions are consistent, evidence-based, and documented","All alerts are ignored until users complain"], correct:2, explain:"Mature handling is structured, traceable, and based on evidence.", reward:"Analyst Mindset" },
  { id:"alert-investigation-348", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the purpose of post-incident review?", options:["To blame the first analyst","To delete old cases","To prove alerts are useless","To learn what worked, what failed, and what should improve"], correct:3, explain:"Post-incident review turns experience into better controls and processes.", reward:"Lessons Learned" },
  { id:"alert-investigation-349", tier:"Beginner", topic:"Alert Investigation", prompt:"Why should alerts be linked to relevant evidence?", options:["Linked evidence helps others verify findings and continue the investigation","Evidence links make alerts automatically true","Links replace analyst notes","Evidence should always be hidden"], correct:0, explain:"Evidence links make case work reviewable and easier to hand off.", reward:"Evidence First" },
  { id:"alert-investigation-350", tier:"Beginner", topic:"Alert Investigation", prompt:"What is the best overall habit in alert investigation?", options:["Close quickly without reading","Follow evidence, ask good questions, document clearly, and escalate when needed","Assume all alerts are false","Disable rules that are hard to understand"], correct:1, explain:"Good investigation is structured, calm, and evidence-driven.", reward:"Analyst Mindset" },
  { id:"alert-investigation-351", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a suspicious process but the host is a known admin jump box. What should change?", options:["Automatically close the alert","Treat host role as context, but still check user, command, target, approval, and timing","Delete all jump-box alerts","Assume every process is malicious"], correct:1, explain:"Admin systems create different baselines but still need evidence-based review.", reward:"Triage Context" },
  { id:"alert-investigation-352", tier:"Intermediate", topic:"Alert Investigation", prompt:"A detection fires after a scheduled software deployment. What should be checked?", options:["Only whether deployment existed","Whether the alert behavior matches the approved deployment details","Only the software icon","Nothing, because all deployments are safe"], correct:1, explain:"Approved changes explain activity only if the activity matches the plan.", reward:"Change Context" },
  { id:"alert-investigation-353", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why can an allowlisted process still be suspicious?", options:["Allowlisting makes all activity malicious","Process names are never logged","Legitimate or allowed processes can be abused with unusual arguments or behavior","Allowlisted processes cannot access files"], correct:2, explain:"Trusted tools can be misused, so behavior still matters.", reward:"Living-off-land Triage" },
  { id:"alert-investigation-354", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows a known admin tool running from a user temp folder. What is suspicious?", options:["Admin tools cannot run from temp folders","The tool name is always malicious","The host has a username","The path may indicate staging or misuse outside normal deployment"], correct:3, explain:"Location can change how suspicious a known tool appears.", reward:"File Triage" },
  { id:"alert-investigation-355", tier:"Intermediate", topic:"Alert Investigation", prompt:"A file hash has low reputation but no execution evidence. What should the analyst do?", options:["Check download, path, prevalence, execution, user, and whether it was blocked or quarantined","Assume compromise is confirmed","Ignore it because it did not execute","Delete unrelated files"], correct:0, explain:"Hash reputation is a lead; behavior and control outcome matter.", reward:"File Triage" },
  { id:"alert-investigation-356", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts distinguish blocked activity from successful activity?", options:["Blocked activity cannot matter at all","Outcome changes risk, scope, and response priority","Blocked alerts should always be deleted","Successful activity is always benign"], correct:1, explain:"A blocked attempt and successful execution require different response decisions.", reward:"Triage Skill" },
  { id:"alert-investigation-357", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert says malware was quarantined. What still needs checking?", options:["Only whether the alert icon changed","Only the user's email address","Whether execution occurred, what launched it, source, related files, and follow-on activity","Nothing; quarantine ends every investigation"], correct:2, explain:"Quarantine helps, but analysts still need to know what happened before and after.", reward:"Malware Triage" },
  { id:"alert-investigation-358", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts check if the same hash appears on other hosts?", options:["Hash spread may indicate wider exposure or repeated delivery","The same hash is always safe","Hashes cannot repeat","It replaces user investigation"], correct:0, explain:"Prevalence across hosts helps scope the incident.", reward:"Scope Control" },
  { id:"alert-investigation-359", tier:"Intermediate", topic:"Alert Investigation", prompt:"A login alert involves a TOR exit node or anonymizer. What should be checked?", options:["Only the alert color","User expectation, MFA, device, location history, session activity, and risk policy","Only whether TOR is spelled correctly","Nothing, because anonymizers are always malicious"], correct:1, explain:"Anonymizer use is suspicious context but needs identity and activity review.", reward:"Identity Triage" },
  { id:"alert-investigation-360", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts check session activity after suspicious authentication?", options:["Session activity is never logged","Authentication alone proves full impact","Session activity shows what the account actually did after login","Session activity replaces MFA"], correct:2, explain:"Post-login actions determine impact and scope.", reward:"Identity Triage" },
  { id:"alert-investigation-361", tier:"Intermediate", topic:"Alert Investigation", prompt:"A risky login is followed by password reset and MFA method change. What is the concern?", options:["Normal DNS maintenance","Possible account takeover and persistence","A harmless software update","A monitor setting change"], correct:1, explain:"Changing recovery or MFA settings after risky access can support continued control.", reward:"Identity Correlation" },
  { id:"alert-investigation-362", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should MFA method changes be investigated after suspicious sign-ins?", options:["MFA methods cannot affect security","MFA changes always mean the user is safe","Attackers may add or remove methods to maintain access","MFA logs are only decorative"], correct:2, explain:"MFA method changes can indicate account takeover steps.", reward:"MFA Triage" },
  { id:"alert-investigation-363", tier:"Intermediate", topic:"Alert Investigation", prompt:"A user denies a suspicious login, but logs show successful MFA approval. What should be considered?", options:["The user is always wrong","The alert must be false positive","MFA fatigue, token/session theft, or mistaken approval may still be possible","Logs should be deleted"], correct:2, explain:"User denial and MFA success require careful follow-up.", reward:"Identity Triage" },
  { id:"alert-investigation-364", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts review cloud activity after account compromise alerts?", options:["Cloud actions cannot create impact","Cloud logs are unrelated to identity","Cloud activity always proves false positive","Compromised accounts may access data, create keys, change roles, or persist"], correct:3, explain:"Cloud activity can reveal impact and attacker objectives.", reward:"Cloud Triage" },
  { id:"alert-investigation-365", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows new access key creation. What should be checked?", options:["Creator, permissions, source IP, related login, key usage, and approval reason","Only whether the key name is short","Only the account display name","Only the dashboard color"], correct:0, explain:"New keys can provide persistent programmatic access.", reward:"Cloud Triage" },
  { id:"alert-investigation-366", tier:"Intermediate", topic:"Alert Investigation", prompt:"A cloud alert shows security group opened to the internet. Why is this important?", options:["Security groups cannot affect access","It may expose services to external scanning or attack","Opening access always improves security","Cloud alerts cannot be true positives"], correct:1, explain:"Network exposure changes can increase attack surface quickly.", reward:"Cloud Triage" },
  { id:"alert-investigation-367", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should be checked in a cloud privilege escalation alert?", options:["Only billing amount","Only the resource name length","Actor, role change, permissions granted, source, approval, and follow-on API calls","Only whether the account has email"], correct:2, explain:"Cloud privilege alerts require identity, permission, and activity context.", reward:"Privilege Triage" },
  { id:"alert-investigation-368", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts review API activity around a cloud alert?", options:["API activity cannot be malicious","API calls are only billing events","API logs replace all identity logs","They show what actions were taken before and after the alert"], correct:3, explain:"Cloud API activity reveals actual behavior and impact.", reward:"Cloud Triage" },
  { id:"alert-investigation-369", tier:"Intermediate", topic:"Alert Investigation", prompt:"An alert shows access to many files in a short time. What context matters?", options:["User role, normal access pattern, file sensitivity, tool used, and destination","Only whether filenames are short","Only the folder color","Only whether the user has a laptop"], correct:0, explain:"Bulk file access can be normal or suspicious depending on context.", reward:"Data Access Triage" },
  { id:"alert-investigation-370", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts check whether data was actually transferred out?", options:["Transfer is impossible to detect","Access alone and exfiltration have different impact and response needs","Data access is never risky","Outbound transfer always means backup"], correct:1, explain:"Impact differs between access, staging, and confirmed exfiltration.", reward:"Exfil Triage" },
  { id:"alert-investigation-371", tier:"Intermediate", topic:"Alert Investigation", prompt:"A data exfiltration alert involves an approved backup service. What should be checked?", options:["Close it immediately","Whether the transfer matches expected backup timing, volume, destination, and source","Delete all backup logs","Assume every backup is malicious"], correct:1, explain:"Approved services can still be misused or misconfigured.", reward:"Business Context" },
  { id:"alert-investigation-372", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should DLP alerts be handled carefully?", options:["They may involve sensitive data, privacy, business process, and user context","DLP alerts are never true","DLP replaces all investigation","DLP alerts cannot contain sensitive information"], correct:0, explain:"DLP cases need careful handling because evidence may itself be sensitive.", reward:"Data Care" },
  { id:"alert-investigation-373", tier:"Intermediate", topic:"Alert Investigation", prompt:"A DLP alert involves source code uploaded externally. What should be reviewed?", options:["Only whether the filename is long","User, destination, approval, repository sensitivity, content type, and business reason","Only the alert color","Nothing if upload succeeded"], correct:1, explain:"Source-code uploads may expose intellectual property or secrets.", reward:"Data Access Triage" },
  { id:"alert-investigation-374", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts check for secrets in exposed files?", options:["Secrets cannot be abused","Secrets are always encrypted in files","Exposed secrets may allow follow-on access and need rotation","Secrets make alerts automatically false"], correct:2, explain:"Credentials or tokens in exposed data can expand incident impact.", reward:"Secret Triage" },
  { id:"alert-investigation-375", tier:"Intermediate", topic:"Alert Investigation", prompt:"What should happen if exposed credentials are confirmed?", options:["Ignore them unless used","Post them in case notes","Treat them as compromised and rotate or revoke according to procedure","Keep them active for investigation only"], correct:2, explain:"Confirmed exposed credentials should be controlled quickly.", reward:"Secret Triage" },
  { id:"alert-investigation-376", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts check whether an alert maps to MITRE ATT&CK?", options:["It may help describe tactics, techniques, and investigation direction","MITRE mapping proves compromise","MITRE replaces evidence","MITRE is only for red teams"], correct:0, explain:"Technique mapping can support structured analysis, but evidence still matters.", reward:"ATT&CK Context" },
  { id:"alert-investigation-377", tier:"Intermediate", topic:"Alert Investigation", prompt:"What is a tactic in MITRE ATT&CK?", options:["A specific hostname","The attacker's broader objective, such as persistence or defense evasion","A firewall vendor name","A password length rule"], correct:1, explain:"Tactics describe why an attacker performs an action.", reward:"ATT&CK Context" },
  { id:"alert-investigation-378", tier:"Intermediate", topic:"Alert Investigation", prompt:"What is a technique in MITRE ATT&CK?", options:["Only the alert severity","Only a SOC shift schedule","A specific method used to achieve a tactic","A dashboard layout"], correct:2, explain:"Techniques describe how attackers perform actions.", reward:"ATT&CK Context" },
  { id:"alert-investigation-379", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should ATT&CK mapping not replace investigation?", options:["Mappings can be wrong or incomplete and still need evidence","ATT&CK always contains all logs","Mappings prove intent automatically","ATT&CK prevents false positives"], correct:0, explain:"Mapping is helpful context, not proof by itself.", reward:"Analyst Mindset" },
  { id:"alert-investigation-380", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should alerts have clear recommended actions?", options:["Recommended actions help analysts investigate consistently and safely","Recommended actions replace evidence","Recommended actions should always be ignored","Recommended actions make alerts malicious"], correct:1, explain:"Clear next steps improve triage speed and quality.", reward:"Playbook Sense" },
  { id:"alert-investigation-381", tier:"Intermediate", topic:"Alert Investigation", prompt:"What makes a recommended action useful?", options:["It is vague enough to fit everything","It tells the analyst what evidence to check and what decision to make next","It says only 'investigate'","It deletes the alert automatically"], correct:1, explain:"Useful recommendations are specific and evidence-focused.", reward:"Playbook Sense" },
  { id:"alert-investigation-382", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should analysts give feedback on unclear alerts?", options:["Feedback helps improve alert title, logic, fields, and investigation guidance","Feedback is only for managers","Unclear alerts cannot be improved","Feedback replaces triage"], correct:0, explain:"Alert quality improves when analysts report what was confusing or missing.", reward:"Lessons Learned" },
  { id:"alert-investigation-383", tier:"Intermediate", topic:"Alert Investigation", prompt:"What is the risk of alert titles that overstate certainty?", options:["They can bias analysts into assuming compromise before evidence is reviewed","They make alerts impossible to close","They prevent escalation","They remove all false positives"], correct:0, explain:"Alert wording should describe behavior without overclaiming.", reward:"Analyst Mindset" },
  { id:"alert-investigation-384", tier:"Intermediate", topic:"Alert Investigation", prompt:"What is the risk of alert titles that are too vague?", options:["They make triage harder because the analyst cannot quickly understand the behavior","They prove the alert is false positive","They prevent logging","They reduce noise automatically"], correct:0, explain:"Clear titles help analysts understand what fired and why.", reward:"Alert Quality" },
  { id:"alert-investigation-385", tier:"Intermediate", topic:"Alert Investigation", prompt:"Why should alert fields use consistent names?", options:["Consistency makes searching, automation, and analyst review easier","Consistent names make all alerts true","Field names prevent attacks","Field names replace event data"], correct:0, explain:"Consistent fields improve workflow and automation reliability.", reward:"Data Source Sense" },
  { id:"alert-investigation-386", tier:"Advanced", topic:"Alert Investigation", prompt:"An endpoint alert, DNS alert, and identity alert all involve the same host within 10 minutes. What is the best interpretation?", options:["This may indicate a connected incident chain and should be correlated before closure","Three alerts always mean false positive","Only the endpoint alert matters","The alerts should be handled as unrelated by default"], correct:0, explain:"Multi-source alerts close in time often deserve correlation.", reward:"Incident Correlation" },
  { id:"alert-investigation-387", tier:"Advanced", topic:"Alert Investigation", prompt:"A suspicious login alert is followed by creation of a mailbox rule and OAuth consent. What should be scoped?", options:["Only the login event","Mailbox activity, app permissions, data accessed, sessions, and other account changes","Only whether the user changed password","Only the alert title"], correct:1, explain:"Identity incidents often persist through mailbox rules, sessions, and app grants.", reward:"Identity Correlation" },
  { id:"alert-investigation-388", tier:"Advanced", topic:"Alert Investigation", prompt:"A host is isolated after malware execution. Why should analysts still investigate related identity activity?", options:["Malware cannot affect credentials","Isolation automatically resets all accounts","Credentials may have been stolen before isolation and used elsewhere","Identity logs are unrelated to malware"], correct:2, explain:"Endpoint containment does not undo credential theft or session abuse.", reward:"Credential Triage" },
  { id:"alert-investigation-389", tier:"Advanced", topic:"Alert Investigation", prompt:"A detection is high fidelity but rarely fires. Why should it still be documented well?", options:["Rare detections are never important","Rare detections should be deleted","Documentation makes it fire more often","When it fires, analysts need to understand why it matters and what to do"], correct:3, explain:"Rare high-value alerts need clear playbooks because analysts may not see them often.", reward:"Playbook Sense" },
  { id:"alert-investigation-390", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should analysts distinguish initial access from impact activity?", options:["Different stages require different scoping, containment, and response questions","Initial access and impact are always identical","Impact activity is never logged","Initial access replaces all later investigation"], correct:0, explain:"Knowing the stage helps prioritize response and missing evidence.", reward:"Attack Chain" },
  { id:"alert-investigation-391", tier:"Advanced", topic:"Alert Investigation", prompt:"A confirmed compromise started weeks ago. Why does this change the investigation?", options:["Older incidents are always harmless","Longer dwell time increases the need to review historical activity and scope impact","Old logs should be ignored","Only the latest alert matters"], correct:1, explain:"Long dwell time can mean more systems, accounts, or data were affected.", reward:"Timeline Sense" },
  { id:"alert-investigation-392", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should responders avoid wiping a host too early?", options:["Wiping can destroy evidence needed for root cause, scope, and lessons learned","Wiping always improves evidence","Hosts cannot be rebuilt","Root cause never matters"], correct:0, explain:"Rebuilds may be needed, but evidence should be considered first.", reward:"Evidence Handling" },
  { id:"alert-investigation-393", tier:"Advanced", topic:"Alert Investigation", prompt:"What is the risk of resetting only one password after account compromise?", options:["Password resets always remove all persistence","Other sessions, tokens, app consents, forwarding rules, or related accounts may remain active","Password resets are never useful","Only passwords matter in identity incidents"], correct:1, explain:"Identity response often needs session, token, app, MFA, and rule review.", reward:"Identity Correlation" },
  { id:"alert-investigation-394", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should an analyst identify all persistence mechanisms before closure?", options:["Persistence cannot survive cleanup","Attackers may regain access if scheduled tasks, services, rules, accounts, or tokens remain","Persistence only exists on servers","Persistence is always visible in one alert"], correct:1, explain:"Incomplete cleanup can allow re-compromise.", reward:"Persistence Triage" },
  { id:"alert-investigation-395", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should containment and eradication be coordinated?", options:["Containment and eradication are the same thing","Eradication should always happen before evidence collection","Poor coordination may tip off attackers, lose evidence, or miss related systems","Coordination prevents all false positives"], correct:2, explain:"Response actions should be planned to reduce risk and preserve investigation value.", reward:"Incident Response" },
  { id:"alert-investigation-396", tier:"Advanced", topic:"Alert Investigation", prompt:"What is the risk of closing an incident after cleaning only the first affected host?", options:["Other affected hosts, accounts, or persistence paths may remain active","The first host is always the only host","Cleaning one host resets all accounts","Scope never matters after cleanup"], correct:0, explain:"Incident closure requires confidence that scope and persistence are handled.", reward:"Scope Control" },
  { id:"alert-investigation-397", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should evidence quality affect confidence level?", options:["Weak, incomplete, or indirect evidence should lead to lower confidence than strong direct evidence","Confidence should ignore evidence","All alerts have equal confidence","Evidence quality only matters in court"], correct:0, explain:"Confidence should honestly reflect how strong the evidence is.", reward:"Evidence First" },
  { id:"alert-investigation-398", tier:"Advanced", topic:"Alert Investigation", prompt:"What is a good response when two evidence sources conflict?", options:["Ignore the source you dislike","Investigate the mismatch, check timestamps, data quality, and source reliability","Close the case immediately","Assume both are wrong"], correct:1, explain:"Conflicting evidence should be resolved or documented clearly.", reward:"Analyst Mindset" },
  { id:"alert-investigation-399", tier:"Advanced", topic:"Alert Investigation", prompt:"Why should alert investigation metrics include quality, not only speed?", options:["Speed always proves good investigations","Fast closure can hide missed threats, weak notes, or poor scoping","Quality cannot be measured","Only queue size matters"], correct:1, explain:"Fast but shallow investigations can create risk.", reward:"Quality Metrics" },
  { id:"alert-investigation-400", tier:"Advanced", topic:"Alert Investigation", prompt:"What is the strongest long-term result of good alert investigations?", options:["Fewer notes written by analysts","More alerts closed without review","Better detections, better playbooks, better controls, and stronger analyst judgment","No need for future monitoring"], correct:2, explain:"Good investigations improve both current response and future defense.", reward:"Lessons Learned" },
];

if (typeof module !== "undefined" && module.exports) module.exports = ALERT_INVESTIGATION_QUESTIONS;
